INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('a9747bc8-10e8-513f-b70c-0006b8316242', '188a4159-c743-5212-96f3-65634e287cd0', 1, '<p>ශ්‍රී ලංකාවේ ඉතිහාසය අඛණ්ඩව රචනා වන කෘතිය මින් කුමක්ද?</p>', '<p>ශ්‍රී ලංකාවේ ඉතිහාසය අඛණ්ඩව රචනා වන කෘතිය මින් කුමක්ද?</p>', NULL, 'ශ්‍රී ලංකාවේ ඉතිහාසය අඛණ්ඩව රචනා වන ප්‍රධානතම වංශකතාව මහාවංසයයි.', 'ශ්‍රී ලංකාවේ ඉතිහාසය අඛණ්ඩව රචනා වන ප්‍රධානතම වංශකතාව මහාවංසයයි.', NULL, 'sanitized', 'v1', 4, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
