INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('710cca02-9fc9-43fb-b802-22b94d6ada2e', '39287f7c-17f6-5c15-8428-e81c983bbe0e', 'ත්‍රිකුණාමලය වරායේ ස්වභාවික පිහිටීමයි.', 'ත්‍රිකුණාමලය වරායේ ස්වභාවික පිහිටීමයි.', NULL, 'sanitized', 'v1', 3, 0);
INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('28642aad-74e0-5102-ae9f-dc063f2ea70a', '188a4159-c743-5212-96f3-65634e287cd0', 10, '<p>වැවක බැම්ම ගිලා නොබැසීම සඳහා අනුගමනය කළ ක්‍රියාමාර්ගයක් වූයේ මින් කුමක්ද?</p>', '<p>වැවක බැම්ම ගිලා නොබැසීම සඳහා අනුගමනය කළ ක්‍රියාමාර්ගයක් වූයේ මින් කුමක්ද?</p>', NULL, 'ජලයේ පීඩනයට වැව් බැම්ම ගිලා නොබැසීම සඳහා ස්වභාවිකව පිහිටි ගල් පර්වත පාදක කරගනිමින් වැව් බැමි ඉදිකිරීම පැරණි වාරි තාක්ෂණයේ ලක්ෂණයකි.', 'ජලයේ පීඩනයට වැව් බැම්ම ගිලා නොබැසීම සඳහා ස්වභාවිකව පිහිටි ගල් පර්වත පාදක කරගනිමින් වැව් බැමි ඉදිකිරීම පැරණි වාරි තාක්ෂණයේ ලක්ෂණයකි.', NULL, 'sanitized', 'v1', 4, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('01a2a732-a334-41d8-81f5-fa3cb278c5f6', '28642aad-74e0-5102-ae9f-dc063f2ea70a', 'පිහිටි ගලක් තෝරා වැව් බැම්ම ඉදිකිරීම', 'පිහිටි ගලක් තෝරා වැව් බැම්ම ඉදිකිරීම', NULL, 'sanitized', 'v1', 0, 1);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('4066f613-b7b1-4fee-9121-ecade591e156', '28642aad-74e0-5102-ae9f-dc063f2ea70a', 'ශක්තිමත් කළු ගලෙන් වැව් බැම්ම ඉදිකිරීම', 'ශක්තිමත් කළු ගලෙන් වැව් බැම්ම ඉදිකිරීම', NULL, 'sanitized', 'v1', 1, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('80ea7506-c481-44ea-bdc1-f408378219e1', '28642aad-74e0-5102-ae9f-dc063f2ea70a', 'පිටවාන මගින් වැඩි ජලය පිටකිරීම', 'පිටවාන මගින් වැඩි ජලය පිටකිරීම', NULL, 'sanitized', 'v1', 2, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('deeb7843-47d1-43d0-b6b1-a9e640c28d5b', '28642aad-74e0-5102-ae9f-dc063f2ea70a', 'සලපනාව ශක්තිමත්ව ඉදිකිරීම', 'සලපනාව ශක්තිමත්ව ඉදිකිරීම', NULL, 'sanitized', 'v1', 3, 0);
INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('ccfa8306-d130-5106-b77c-e02f6182c23e', '188a4159-c743-5212-96f3-65634e287cd0', 11, '<p>පහත A සිට E දක්වා ප්‍රකාශ හොඳින් කියවා 11 සහ 12 ප්‍රශ්න සඳහා පිළිතුරු සපයන්න.<br><br>A - උද්‍යාන සැලසුම්කරණය පිළිබඳ විශිෂ්ට දැනුමක් තිබීම<br>B - ආරක්ෂාව සඳහා දිය අගල් හා ගඩොල් ප්‍රාකාර භාවිත කිරීම<br>C - අත්තිවාරම සැකසීම නූතන කොන්ක්‍රීට් තාක්ෂණයට සමාන වීම<br>D - සනීපාරක්ෂාව හා ස්වස්ථතාව පිළිබඳ මනා දැනුමක් තිබීම<br>E - ශල්‍ය වෛද්‍ය උපකරණ භාවිත කළ බවට සාධක හමු වීම<br><br>සීගිරිය සම්බන්ධ තොරතුරු දැක්වෙන පිළිතුර කුමක්ද?</p>', '<p>පහත A සිට E දක්වා ප්‍රකාශ හොඳින් කියවා 11 සහ 12 ප්‍රශ්න සඳහා පිළිතුරු සපයන්න.<br><br>A - උද්‍යාන සැලසුම්කරණය පිළිබඳ විශිෂ්ට දැනුමක් තිබීම<br>B - ආරක්ෂාව සඳහා දිය අගල් හා ගඩොල් ප්‍රාකාර භාවිත කිරීම<br>C - අත්තිවාරම සැකසීම නූතන කොන්ක්‍රීට් තාක්ෂණයට සමාන වීම<br>D - සනීපාරක්ෂාව හා ස්වස්ථතාව පිළිබඳ මනා දැනුමක් තිබීම<br>E - ශල්‍ය වෛද්‍ය උපකරණ භාවිත කළ බවට සාධක හමු වීම<br><br>සීගිරිය සම්බන්ධ තොරතුරු දැක්වෙන පිළිතුර කුමක්ද?</p>', NULL, 'සීගිරියේ ජල උද්‍යාන සහ දිය අගල්, ප්‍රාකාර ආදිය මගින් පැරණි උද්‍යාන සැලසුම්කරණය (A) සහ ආරක්ෂක විධිවිධාන (B) මනාව පැහැදිලි වේ.', 'සීගිරියේ ජල උද්‍යාන සහ දිය අගල්, ප්‍රාකාර ආදිය මගින් පැරණි උද්‍යාන සැලසුම්කරණය (A) සහ ආරක්ෂක විධිවිධාන (B) මනාව පැහැදිලි වේ.', NULL, 'sanitized', 'v1', 4, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
