INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('c7fe2de5-0e0c-5c9f-92e9-3ed0a1130e48', '188a4159-c743-5212-96f3-65634e287cd0', 20, '<p>දුරදක්නය නිපදවනු ලැබුවේ කවුරුන් විසින්ද?</p>', '<p>දුරදක්නය නිපදවනු ලැබුවේ කවුරුන් විසින්ද?</p>', NULL, 'අභ්‍යවකාශ ගවේෂණය සඳහා බෙහෙවින් උපකාරී වූ දුරදක්නය (Telescope) නිර්මාණය කරන ලද්දේ ගැලීලියෝ ගැලිලි විසිනි.', 'අභ්‍යවකාශ ගවේෂණය සඳහා බෙහෙවින් උපකාරී වූ දුරදක්නය (Telescope) නිර්මාණය කරන ලද්දේ ගැලීලියෝ ගැලිලි විසිනි.', NULL, 'sanitized', 'v1', 4, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
