INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('ebfa2a87-4c7a-43de-85f8-010bf299f239', 'f776bbef-7a91-5785-a0c1-dc9a63bf5977', '1833 කෝල්බෲක් - කැමරන් ප්‍රතිසංස්කරණ වලින් පසුව ය.', '1833 කෝල්බෲක් - කැමරන් ප්‍රතිසංස්කරණ වලින් පසුව ය.', NULL, 'sanitized', 'v1', 3, 0);
INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('537a9ef8-0515-560f-bca1-397b0c76c766', '188a4159-c743-5212-96f3-65634e287cd0', 25, '<p>ශ්‍රී ලංකාවේ ත්‍රිකුණාමලය වරාය කෙරෙහි ඉංග්‍රීසින්ගේ අවධානය යොමු වීමට ප්‍රධානතම හේතුව වූයේ,</p>', '<p>ශ්‍රී ලංකාවේ ත්‍රිකුණාමලය වරාය කෙරෙහි ඉංග්‍රීසින්ගේ අවධානය යොමු වීමට ප්‍රධානතම හේතුව වූයේ,</p>', NULL, 'බෙංගාල බොක්ක සහ ඉන්දියාවේ නැගෙනහිර වෙරළ තීරයේ තම නාවික ආධිපත්‍යය තහවුරු කරගැනීමට ත්‍රිකුණාමලය වරායේ පිහිටීම ඉංග්‍රීසීන්ට උපායමාර්ගිකව වැදගත් විය.', 'බෙංගාල බොක්ක සහ ඉන්දියාවේ නැගෙනහිර වෙරළ තීරයේ තම නාවික ආධිපත්‍යය තහවුරු කරගැනීමට ත්‍රිකුණාමලය වරායේ පිහිටීම ඉංග්‍රීසීන්ට උපායමාර්ගිකව වැදගත් විය.', NULL, 'sanitized', 'v1', 4, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
