INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('19d89047-80fa-4fb4-940c-c5f6e4f4347b', 'ed97f64c-b030-5eb6-94da-1c2dffead5b1', 'බීජ හටගන්නා සහ බීජ හට නොගන්නා යනුවෙන් සපුෂ්ප ශාක තාණ්ඩ දෙකක් ඇත.', 'බීජ හටගන්නා සහ බීජ හට නොගන්නා යනුවෙන් සපුෂ්ප ශාක තාණ්ඩ දෙකක් ඇත.', NULL, 'sanitized', 'v1', 3, 0);
INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('0ca8d209-ca81-5ee0-ad4b-4a90a48a5de8', '18e1b495-aa0a-5ae6-aa71-59ed1edd82eb', 6, '<p>රුධිර සංසරණ පද්ධතියෙහි ඇති සෛලයක්. පටකයක් සහ ඉන්ද්‍රියයක් වන්නේ පිළිවෙළින්</p>', '<p>රුධිර සංසරණ පද්ධතියෙහි ඇති සෛලයක්. පටකයක් සහ ඉන්ද්‍රියයක් වන්නේ පිළිවෙළින්</p>', NULL, 'නියුට්‍රොෆිල යනු සුදු රුධිර සෛල වර්ගයකි (සෛලය). රුධිරය යනු ද්‍රව සම්බන්ධක පටකයකි (පටකය). රුධිර වාහිනී යනු විවිධ පටක එක් වී සෑදුණු අවයවයකි (ඉන්ද්‍රියය).', 'නියුට්‍රොෆිල යනු සුදු රුධිර සෛල වර්ගයකි (සෛලය). රුධිරය යනු ද්‍රව සම්බන්ධක පටකයකි (පටකය). රුධිර වාහිනී යනු විවිධ පටක එක් වී සෑදුණු අවයවයකි (ඉන්ද්‍රියය).', NULL, 'sanitized', 'v1', 4, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('4b1e477b-ba5b-4d26-96c0-a393cc2f345e', '0ca8d209-ca81-5ee0-ad4b-4a90a48a5de8', 'නියුට්‍රොෆිල, රුධිරය සහ රුධිර වාහිනීය.', 'නියුට්‍රොෆිල, රුධිරය සහ රුධිර වාහිනීය.', NULL, 'sanitized', 'v1', 0, 1);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('bef36366-3200-4f13-b1be-eb38bbb2ed92', '0ca8d209-ca81-5ee0-ad4b-4a90a48a5de8', 'පට්ටිකා, රුධිර ප්ලාස්මාව සහ රුධිර වාහිනීය.', 'පට්ටිකා, රුධිර ප්ලාස්මාව සහ රුධිර වාහිනීය.', NULL, 'sanitized', 'v1', 1, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('62e52c8a-95ab-4415-8dbc-862c0c84584c', '0ca8d209-ca81-5ee0-ad4b-4a90a48a5de8', 'රුධිර කේශනාලිකා, ධමනි සහ හෘදය ය.', 'රුධිර කේශනාලිකා, ධමනි සහ හෘදය ය.', NULL, 'sanitized', 'v1', 2, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('633afe20-c280-44b8-b415-bfeaade459fb', '0ca8d209-ca81-5ee0-ad4b-4a90a48a5de8', 'ඉයොසිනොෆිල, රුධිර කේශනාලිකා සහ හෘදය ය.', 'ඉයොසිනොෆිල, රුධිර කේශනාලිකා සහ හෘදය ය.', NULL, 'sanitized', 'v1', 3, 0);
INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('3da423bd-ecd0-5246-866e-4c9bcba2eddf', '18e1b495-aa0a-5ae6-aa71-59ed1edd82eb', 7, '<p>පහත දැක්වෙන කුමන ප්‍රභේදයෙහි ඉලෙක්ට්‍රෝන 10ක්, ප්‍රෝටෝන 11ක් හා නියුට්‍රෝන 12 ක් අඩංගු වේද?</p>', '<p>පහත දැක්වෙන කුමන ප්‍රභේදයෙහි ඉලෙක්ට්‍රෝන 10ක්, ප්‍රෝටෝන 11ක් හා නියුට්‍රෝන 12 ක් අඩංගු වේද?</p>', NULL, 'ප්‍රෝටෝන 11 ක් අඩංගු මූලද්‍රව්‍යය සෝඩියම් ($Na$) වේ. නියුට්‍රෝන 12 ක් ඇති බැවින් ස්කන්ධ ක්‍රමාංකය $11 + 12 = 23$ වේ. ඉලෙක්ට්‍රෝන 10 ක් ඇති බැවින් එහි $+1$ ආරෝපණයක් තිබිය යුතුය. එනම් අයනය ${}_{11}^{23}Na^{+}$ වේ.', 'ප්‍රෝටෝන 11 ක් අඩංගු මූලද්‍රව්‍යය සෝඩියම් ($Na$) වේ. නියුට්‍රෝන 12 ක් ඇති බැවින් ස්කන්ධ ක්‍රමාංකය $11 + 12 = 23$ වේ. ඉලෙක්ට්‍රෝන 10 ක් ඇති බැවින් එහි $+1$ ආරෝපණයක් තිබිය යුතුය. එනම් අයනය ${}_{11}^{23}Na^{+}$ වේ.', NULL, 'sanitized', 'v1', 4, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
