INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('598f6e31-d68c-4b5e-8548-eed8e4bd1158', '2ffdbef8-1fca-52bd-9e3b-a0eb5fa166b0', 'අතාත්වික හා උඩුකුරු වන අතර වස්තුවට වඩා විශාල වේ.', 'අතාත්වික හා උඩුකුරු වන අතර වස්තුවට වඩා විශාල වේ.', NULL, 'sanitized', 'v1', 3, 0);
INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('22cdc5d4-14d0-50e5-8361-e1bfdfd2fad6', '18e1b495-aa0a-5ae6-aa71-59ed1edd82eb', 12, '<p>පරිණාමකයකට 230 V සැපයුමකින් 690 W ජවයක් සපයා ඇත. දඟරයට සැපයෙන ධාරාව කොපමණද?</p>', '<p>පරිණාමකයකට 230 V සැපයුමකින් 690 W ජවයක් සපයා ඇත. දඟරයට සැපයෙන ධාරාව කොපමණද?</p>', NULL, 'විද්‍යුත් ජවය සඳහා සමීකරණය $P = VI$ වේ.<br>$690 = 230 \times I$<br>$I = 690 / 230 = 3 A$.', 'විද්‍යුත් ජවය සඳහා සමීකරණය $P = VI$ වේ.<br>$690 = 230 \times I$<br>$I = 690 / 230 = 3 A$.', NULL, 'sanitized', 'v1', 4, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
