INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('33462039-c7bb-5ce2-b150-d5f0f3ac54d1', '18e1b495-aa0a-5ae6-aa71-59ed1edd82eb', 20, '<p>අණුක සූත්‍රය $C_{5}H_{12}$ වූ හයිඩ්රොකාබනය</p>', '<p>අණුක සූත්‍රය $C_{5}H_{12}$ වූ හයිඩ්රොකාබනය</p>', NULL, '$C_5H_{12}$ යනු ඇල්කේනයකි (පෙන්ටේන්). එහි හයිඩ්රජන් පරමාණු 12 ක් ඇති බැවින්, මවුල 1 ක් පූර්ණ දහනය වීමේදී ජලය ($H_2O$) මවුල 6 ක් සෑදේ.', '$C_5H_{12}$ යනු ඇල්කේනයකි (පෙන්ටේන්). එහි හයිඩ්රජන් පරමාණු 12 ක් ඇති බැවින්, මවුල 1 ක් පූර්ණ දහනය වීමේදී ජලය ($H_2O$) මවුල 6 ක් සෑදේ.', NULL, 'sanitized', 'v1', 4, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
