INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('6fb71b51-5e0c-4421-bb23-e19027ab4809', '33462039-c7bb-5ce2-b150-d5f0f3ac54d1', 'මවුලයක් පුර්ණ දහනයේ දී ජලය මවුල 6ක් සෑදේ.', 'මවුලයක් පුර්ණ දහනයේ දී ජලය මවුල 6ක් සෑදේ.', NULL, 'sanitized', 'v1', 3, 0);
INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('81f8c04f-c52c-50c2-abb0-63e0cd7a8118', '18e1b495-aa0a-5ae6-aa71-59ed1edd82eb', 21, '<p>පෙර නැඹුරු කර ඇති ඩයෝඩයක p-n සන්ධිය හරහා පහසුවෙන් ඉලෙක්ට්‍රෝන ගලා යාමට ප්‍රධාන හේතුව වන්නේ,</p>', '<p>පෙර නැඹුරු කර ඇති ඩයෝඩයක p-n සන්ධිය හරහා පහසුවෙන් ඉලෙක්ට්‍රෝන ගලා යාමට ප්‍රධාන හේතුව වන්නේ,</p>', NULL, 'p-n සන්ධියක් පෙර නැඹුරු (Forward bias) කළ විට එහි හායිත ප්‍රදේශය (Depletion region) ඉතා පටු වේ. මේ නිසා සන්ධිය හරහා ඇති විභව බාධකය කුඩා වී බහුතර වාහකයන්ට පහසුවෙන් ගමන් කළ හැක.', 'p-n සන්ධියක් පෙර නැඹුරු (Forward bias) කළ විට එහි හායිත ප්‍රදේශය (Depletion region) ඉතා පටු වේ. මේ නිසා සන්ධිය හරහා ඇති විභව බාධකය කුඩා වී බහුතර වාහකයන්ට පහසුවෙන් ගමන් කළ හැක.', NULL, 'sanitized', 'v1', 4, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
