INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('a640aef8-bdab-4dfd-a8c8-b3d9cd228d8c', '81f8c04f-c52c-50c2-abb0-63e0cd7a8118', 'හායිත ප්‍රදේශය ඉතා පටු වීම යි.', 'හායිත ප්‍රදේශය ඉතා පටු වීම යි.', NULL, 'sanitized', 'v1', 2, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('54c2a081-4fa8-4f58-84cf-52d41bbd528e', '81f8c04f-c52c-50c2-abb0-63e0cd7a8118', 'මාත්‍රණ මට්ටම ඉතා අඩු වීම යි.', 'මාත්‍රණ මට්ටම ඉතා අඩු වීම යි.', NULL, 'sanitized', 'v1', 3, 0);
INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('a7c1e5fc-e339-53ae-970e-eef351c20870', '18e1b495-aa0a-5ae6-aa71-59ed1edd82eb', 22, '<p>ඝනත්ව පිළිවෙළින් $\\rho_{A}$ හා $\\rho_{B}$ වන A හා B අමිශ්‍ය ද්‍රව දෙකක් ඇත. ඝනත්ව පිළිවෙළින් $\\rho_{X}, \\rho_{Y}$ හා $\\rho_{Z}$ වන සමාන අරයන්ගෙන් යුත් X, Y හා Z ඝන ගෝල තුනක් රූපයේ පරිදි ද්‍රව තුළ පිහිටයි. ඒ පිළිබඳව නිවැරදි ප්‍රකාශය කුමක්ද?</p>
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('a210929e-c7d8-4332-aac3-f7af49a368dc', 'a7c1e5fc-e339-53ae-970e-eef351c20870', '$\rho_{A}<\rho_{B}$ වන අතර $\rho_{X}<\rho_{Y}<\rho_{Z}$ වේ.', '$\rho_{A}<\rho_{B}$ වන අතර $\rho_{X}<\rho_{Y}<\rho_{Z}$ වේ.', NULL, 'sanitized', 'v1', 0, 1);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('5b27cbb6-40be-4913-8ad9-a1b588eec5a3', 'a7c1e5fc-e339-53ae-970e-eef351c20870', '$\rho_{A}<\rho_{B}$ වන අතර $\rho_{X}=\rho_{Y}<\rho_{Z}$ වේ.', '$\rho_{A}<\rho_{B}$ වන අතර $\rho_{X}=\rho_{Y}<\rho_{Z}$ වේ.', NULL, 'sanitized', 'v1', 1, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('3b13b44d-83b4-4de8-91af-c2ba54429203', 'a7c1e5fc-e339-53ae-970e-eef351c20870', '$\rho_{A}=\rho_{X}=\rho_{Y}$ වන අතර $\rho_{B}<\rho_{Z}$ වේ.', '$\rho_{A}=\rho_{X}=\rho_{Y}$ වන අතර $\rho_{B}<\rho_{Z}$ වේ.', NULL, 'sanitized', 'v1', 2, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('a7e549d5-1df5-4f35-a946-4968166d5d54', 'a7c1e5fc-e339-53ae-970e-eef351c20870', '$\rho_{A}=\rho_{X}<\rho_{Y}$ වන අතර $\rho_{B}=\rho_{Z}$ වේ.', '$\rho_{A}=\rho_{X}<\rho_{Y}$ වන අතර $\rho_{B}=\rho_{Z}$ වේ.', NULL, 'sanitized', 'v1', 3, 0);
INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('67de44d8-379b-5637-8f3d-7c3c082641b6', '18e1b495-aa0a-5ae6-aa71-59ed1edd82eb', 23, '<p>V සහ W යනු ක්‍රියතා ශ්‍රේණියේ හයිඩ්රජන්වලට ඉහළින් පිහිටි ලෝහ තුනකි. මේවායේ ක්‍රියතා සැසඳීම සඳහා ශිෂ්‍ය කණ්ඩායමක් විසින් යෝජනා කරන ලද ක්‍රමය වුයේ ලෝහ තුනෙන් කැබැල්ල බැගින් ගෙන හයිඩ්රොක්ලෝරික් අම්ලය සමඟ වෙන වෙන ම ප්‍රතික්‍රියා කරවා නියත කෙටි කාලයක දී මුක්ත වූ හයිඩ්රජන් වායු පරිමා සැසඳීම ය. පරීක්ෂණයේ දී නියත ව පවත්වා ගැනීම අත්‍යවශ්‍ය නොවන්නේ පහත කුමන සාධකය ද?</p>', '<p>V සහ W යනු ක්‍රියතා ශ්‍රේණියේ හයිඩ්රජන්වලට ඉහළින් පිහිටි ලෝහ තුනකි. මේවායේ ක්‍රියතා සැසඳීම සඳහා ශිෂ්‍ය කණ්ඩායමක් විසින් යෝජනා කරන ලද ක්‍රමය වුයේ ලෝහ තුනෙන් කැබැල්ල බැගින් ගෙන හයිඩ්රොක්ලෝරික් අම්ලය සමඟ වෙන වෙන ම ප්‍රතික්‍රියා කරවා නියත කෙටි කාලයක දී මුක්ත වූ හයිඩ්රජන් වායු පරිමා සැසඳීම ය. පරීක්ෂණයේ දී නියත ව පවත්වා ගැනීම අත්‍යවශ්‍ය නොවන්නේ පහත කුමන සාධකය ද?</p>', NULL, 'නියත කෙටි කාලයකදී පිටවන වායු පරිමාව මැනීමෙන් ප්‍රතික්‍රියා ශීඝ්‍රතාව සසඳන බැවින්, ශීඝ්‍රතාවට බලපාන සාධක වන පෘෂ්ඨික වර්ගඵලය, උෂ්ණත්වය සහ අම්ලයේ සාන්ද්‍රණය නියතව තබා ගත යුතුය. මෙහිදී ලෝහවල ස්කන්ධය සමාන වීම අත්‍යවශ්‍ය නොවේ.', 'නියත කෙටි කාලයකදී පිටවන වායු පරිමාව මැනීමෙන් ප්‍රතික්‍රියා ශීඝ්‍රතාව සසඳන බැවින්, ශීඝ්‍රතාවට බලපාන සාධක වන පෘෂ්ඨික වර්ගඵලය, උෂ්ණත්වය සහ අම්ලයේ සාන්ද්‍රණය නියතව තබා ගත යුතුය. මෙහිදී ලෝහවල ස්කන්ධය සමාන වීම අත්‍යවශ්‍ය නොවේ.', NULL, 'sanitized', 'v1', 4, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
