INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('46ed9abd-0475-489c-be94-b365f3924729', 'b47577ad-d530-5915-9737-9fb10179d3a7', 'දුම්රිය මත ක්‍රියාකරන වාත ප්‍රතිරෝධය අවම වීම', 'දුම්රිය මත ක්‍රියාකරන වාත ප්‍රතිරෝධය අවම වීම', NULL, 'sanitized', 'v1', 2, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('602d0e3f-1157-4df2-badd-12d630b16e0d', 'b47577ad-d530-5915-9737-9fb10179d3a7', 'අවම ඝර්ෂණය යටතේ දුම්රිය ධාවනය වීම', 'අවම ඝර්ෂණය යටතේ දුම්රිය ධාවනය වීම', NULL, 'sanitized', 'v1', 3, 0);
INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('f7a5c81b-9b8d-56d4-8e1c-4243bf082d6d', '18e1b495-aa0a-5ae6-aa71-59ed1edd82eb', 32, '<p>විද්‍යාගාරයේ දී $H_{2}$ සහ $CO_{2}$ වායු නිපදවා ගැනීම සඳහා භාවිත කරන ප්‍රතික්‍රියා දෙකක් පහත දැක්වේ.<br>$Zn+2HCl\rightarrow ZnCl_{2}+H_{2}$<br>$CaCO_{3}+2HCl\longrightarrow CaCl_{2}+H_{2}O+CO_{2}$<br>සින්ක් (Zn) 32 g කින් ලැබිය හැකි උපරිම $H_{2}$ වායු මවුල ප්‍රමාණයට සමාන $CO_{2}$ වායු මවුල ප්‍රමාණයක් ලබා ගැනීම සඳහා ප්‍රතික්‍රියා කරවිය යුතු $CaCO_{3}$ ස්කන්ධය කොපමණ ද?<br>($H = 1$; $C=12$; $O=16;$ $Ca=40$; $Zn=64$)</p>', '<p>විද්‍යාගාරයේ දී $H_{2}$ සහ $CO_{2}$ වායු නිපදවා ගැනීම සඳහා භාවිත කරන ප්‍රතික්‍රියා දෙකක් පහත දැක්වේ.<br>$Zn+2HCl\rightarrow ZnCl_{2}+H_{2}$<br>$CaCO_{3}+2HCl\longrightarrow CaCl_{2}+H_{2}O+CO_{2}$<br>සින්ක් (Zn) 32 g කින් ලැබිය හැකි උපරිම $H_{2}$ වායු මවුල ප්‍රමාණයට සමාන $CO_{2}$ වායු මවුල ප්‍රමාණයක් ලබා ගැනීම සඳහා ප්‍රතික්‍රියා කරවිය යුතු $CaCO_{3}$ ස්කන්ධය කොපමණ ද?<br>($H = 1$; $C=12$; $O=16;$ $Ca=40$; $Zn=64$)</p>', NULL, 'සින්ක් මවුල ගණන $= 32g / 64 gmol^{-1} = 0.5 mol$.<br>සමීකරණයට අනුව නිපදවෙන $H_2$ මවුල ගණන ද $0.5 mol$ වේ.<br>$CO_2$ මවුල $0.5$ ක් සෑදීමට $CaCO_3$ මවුල $0.5$ ක් අවශ්‍ය වේ.<br>$CaCO_3$ හි මවුලික ස්කන්ධය $= 100 gmol^{-1}$.<br>අවශ්‍ය ස්කන්ධය $= 0.5 mol \times 100 gmol^{-1} = 50 g$.', 'සින්ක් මවුල ගණන $= 32g / 64 gmol^{-1} = 0.5 mol$.<br>සමීකරණයට අනුව නිපදවෙන $H_2$ මවුල ගණන ද $0.5 mol$ වේ.<br>$CO_2$ මවුල $0.5$ ක් සෑදීමට $CaCO_3$ මවුල $0.5$ ක් අවශ්‍ය වේ.<br>$CaCO_3$ හි මවුලික ස්කන්ධය $= 100 gmol^{-1}$.<br>අවශ්‍ය ස්කන්ධය $= 0.5 mol \times 100 gmol^{-1} = 50 g$.', NULL, 'sanitized', 'v1', 4, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
