INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('a0d3e658-ad76-5939-8906-701d70fc4009', '192ba85b-45c0-5e6a-9440-9b77c29515ec', 1, '<p>Which of the following physical quantities has the unit $J\ s$?</p>', '<p>Which of the following physical quantities has the unit $J\ s$?</p>', NULL, 'The unit of energy (Joule) is $kg\ m^2\ s^{-2}$. Therefore, $J\ s = kg\ m^2\ s^{-1}$.<br>Angular momentum $L = mvr$, which has units $kg\ (m\ s^{-1})\ m = kg\ m^2\ s^{-1}$.<br>Thus, $J\ s$ is the unit of angular momentum.', 'The unit of energy (Joule) is $kg\ m^2\ s^{-2}$. Therefore, $J\ s = kg\ m^2\ s^{-1}$.<br>Angular momentum $L = mvr$, which has units $kg\ (m\ s^{-1})\ m = kg\ m^2\ s^{-1}$.<br>Thus, $J\ s$ is the unit of angular momentum.', NULL, 'sanitized', 'v1', 5, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
