INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('23fb997a-ba43-597d-94c8-94326416e1ed', '192ba85b-45c0-5e6a-9440-9b77c29515ec', 3, '<p>Two coplanar vectors $A$ and $B$ have magnitudes $3\ N$ and $4\ N$ respectively. If the angle between them is $60^\circ$, what is the magnitude of their resultant?</p>', '<p>Two coplanar vectors $A$ and $B$ have magnitudes $3\ N$ and $4\ N$ respectively. If the angle between them is $60^\circ$, what is the magnitude of their resultant?</p>', NULL, 'The magnitude of the resultant vector $R$ is given by the cosine rule:<br>$R = \sqrt{A^2 + B^2 + 2AB\cos\theta}$<br>$R = \sqrt{3^2 + 4^2 + 2(3)(4)\cos(60^\circ)}$<br>$R = \sqrt{9 + 16 + 24(0.5)} = \sqrt{25 + 12} = \sqrt{37}\ N$.', 'The magnitude of the resultant vector $R$ is given by the cosine rule:<br>$R = \sqrt{A^2 + B^2 + 2AB\cos\theta}$<br>$R = \sqrt{3^2 + 4^2 + 2(3)(4)\cos(60^\circ)}$<br>$R = \sqrt{9 + 16 + 24(0.5)} = \sqrt{25 + 12} = \sqrt{37}\ N$.', NULL, 'sanitized', 'v1', 5, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
