INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('5e202052-c674-5c47-bcdf-c6a2529cb569', '192ba85b-45c0-5e6a-9440-9b77c29515ec', 4, '<p>A particle undergoes uniform circular motion with a constant speed $v$ in a circle of radius $r$. Which of the following statements is true regarding its acceleration?</p>', '<p>A particle undergoes uniform circular motion with a constant speed $v$ in a circle of radius $r$. Which of the following statements is true regarding its acceleration?</p>', NULL, 'In uniform circular motion, the speed is constant, but the velocity vector is continuously changing direction. This change in velocity requires a centripetal acceleration, which is always directed towards the center of the circle and has a magnitude of $a = \frac{v^2}{r}$. Its direction changes continuously as the particle moves, so it is not constant in direction.', 'In uniform circular motion, the speed is constant, but the velocity vector is continuously changing direction. This change in velocity requires a centripetal acceleration, which is always directed towards the center of the circle and has a magnitude of $a = \frac{v^2}{r}$. Its direction changes continuously as the particle moves, so it is not constant in direction.', NULL, 'sanitized', 'v1', 5, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('5bbc4f8f-13b7-41e2-a075-dab20177cdd0', '5e202052-c674-5c47-bcdf-c6a2529cb569', 'The acceleration is zero because the speed is constant.', 'The acceleration is zero because the speed is constant.', NULL, 'sanitized', 'v1', 0, 1);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('1c00101f-e1f3-4ae3-b4d0-fb8ec4da34b1', '5e202052-c674-5c47-bcdf-c6a2529cb569', 'The acceleration is tangent to the circular path.', 'The acceleration is tangent to the circular path.', NULL, 'sanitized', 'v1', 1, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('2b4b48ff-80f0-4b7a-b1c4-a7c87bfb507d', '5e202052-c674-5c47-bcdf-c6a2529cb569', 'The acceleration is directed towards the center of the circle with magnitude $\frac{v^2}{r}$.', 'The acceleration is directed towards the center of the circle with magnitude $\frac{v^2}{r}$.', NULL, 'sanitized', 'v1', 2, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('f6d0d96b-a79f-4b91-9d0e-a4d697d004ee', '5e202052-c674-5c47-bcdf-c6a2529cb569', 'The acceleration is directed outwards from the center of the circle.', 'The acceleration is directed outwards from the center of the circle.', NULL, 'sanitized', 'v1', 3, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('dc2b4470-47d9-4dca-bccf-0aa4178e23ba', '5e202052-c674-5c47-bcdf-c6a2529cb569', 'The acceleration is constant in both magnitude and direction.', 'The acceleration is constant in both magnitude and direction.', NULL, 'sanitized', 'v1', 4, 0);
INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('6bd2793a-9c1c-5ca0-94f5-ee1bb77419ca', '192ba85b-45c0-5e6a-9440-9b77c29515ec', 5, '<p>A block of mass $m$ is resting on a rough horizontal surface. A gradually increasing horizontal force $F$ is applied to the block. The block begins to move when $F = F_0$. What is the coefficient of static friction $\mu_s$ between the block and the surface?</p>', '<p>A block of mass $m$ is resting on a rough horizontal surface. A gradually increasing horizontal force $F$ is applied to the block. The block begins to move when $F = F_0$. What is the coefficient of static friction $\mu_s$ between the block and the surface?</p>', NULL, 'The block begins to move when the applied force overcomes the maximum static friction force.<br>Maximum static friction $f_{s(max)} = \mu_s N$, where the normal force $N = mg$.<br>Equating the forces at the point of slipping: $F_0 = \mu_s mg$.<br>Therefore, $\mu_s = \frac{F_0}{mg}$.', 'The block begins to move when the applied force overcomes the maximum static friction force.<br>Maximum static friction $f_{s(max)} = \mu_s N$, where the normal force $N = mg$.<br>Equating the forces at the point of slipping: $F_0 = \mu_s mg$.<br>Therefore, $\mu_s = \frac{F_0}{mg}$.', NULL, 'sanitized', 'v1', 5, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
