INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('dd25f10d-52e6-5505-9ac4-5afb4d07d7d6', '192ba85b-45c0-5e6a-9440-9b77c29515ec', 6, '<p>Consider following statements about a muon ($\mu$).<br>(A) It is a lepton.<br>(B) It is made out of three quarks.<br>(C) Its mass is larger than that of an electron.<br><br>Of the above statements,</p>', '<p>Consider following statements about a muon ($\mu$).<br>(A) It is a lepton.<br>(B) It is made out of three quarks.<br>(C) Its mass is larger than that of an electron.<br><br>Of the above statements,</p>', NULL, '(A) is true: A muon is an elementary particle classified as a lepton.<br>(B) is false: Since it is an elementary particle (a lepton), it is not composed of quarks. Particles made of three quarks are baryons (like protons and neutrons).<br>(C) is true: The mass of a muon is approximately 207 times the mass of an electron.<br>Therefore, only (A) and (C) are true.', '(A) is true: A muon is an elementary particle classified as a lepton.<br>(B) is false: Since it is an elementary particle (a lepton), it is not composed of quarks. Particles made of three quarks are baryons (like protons and neutrons).<br>(C) is true: The mass of a muon is approximately 207 times the mass of an electron.<br>Therefore, only (A) and (C) are true.', NULL, 'sanitized', 'v1', 5, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
