INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('076ddc9f-b575-560a-a7dd-882283549f39', '192ba85b-45c0-5e6a-9440-9b77c29515ec', 7, '<p>The graph of the variation of velocity ($v$) with time ($t$) of an object is shown in the figure.<br><br>The corresponding displacement ($s$)-time ($t$) curve is best represented by</p>', '<p>The graph of the variation of velocity ($v$) with time ($t$) of an object is shown in the figure.<br><br>The corresponding displacement ($s$)-time ($t$) curve is best represented by</p>', NULL, 'Let''s analyze the velocity-time ($v-t$) graph:<br>1. In the first interval, velocity increases linearly from zero. This indicates constant positive acceleration. The displacement-time ($s-t$) graph should be a curve with an increasing positive slope (concave up).<br>2. In the second interval, velocity is constant and positive. Acceleration is zero. The $s-t$ graph should be a straight line with a constant positive slope.<br>3. In the third interval, velocity decreases linearly, crosses zero, and becomes negative. This indicates constant negative acceleration. The $s-t$ graph should be a curve with a decreasing slope (concave down), reaching a local maximum where $v=0$, and then having a negative slope. Graph 4 perfectly matches all these phases.', 'Let''s analyze the velocity-time ($v-t$) graph:<br>1. In the first interval, velocity increases linearly from zero. This indicates constant positive acceleration. The displacement-time ($s-t$) graph should be a curve with an increasing positive slope (concave up).<br>2. In the second interval, velocity is constant and positive. Acceleration is zero. The $s-t$ graph should be a straight line with a constant positive slope.<br>3. In the third interval, velocity decreases linearly, crosses zero, and becomes negative. This indicates constant negative acceleration. The $s-t$ graph should be a curve with a decreasing slope (concave down), reaching a local maximum where $v=0$, and then having a negative slope. Graph 4 perfectly matches all these phases.', NULL, 'sanitized', 'v1', 5, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
