INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('d1679ccd-ab2f-54da-a908-848b5e461994', '192ba85b-45c0-5e6a-9440-9b77c29515ec', 9, '<p>An astronomical telescope is in normal adjustment. If the focal length of objective lens is $80\ cm$ and the angular magnification is 20, what is the distance between the objective lens and the eyepiece?</p>', '<p>An astronomical telescope is in normal adjustment. If the focal length of objective lens is $80\ cm$ and the angular magnification is 20, what is the distance between the objective lens and the eyepiece?</p>', NULL, 'For an astronomical telescope in normal adjustment, the final image is formed at infinity. The angular magnification $M$ is given by $M = \frac{f_o}{f_e}$, where $f_o$ is the focal length of the objective lens and $f_e$ is the focal length of the eyepiece.<br>Given $M = 20$ and $f_o = 80\ cm$, we have $20 = \frac{80}{f_e} \implies f_e = 4\ cm$.<br>The distance between the objective lens and the eyepiece in normal adjustment is $L = f_o + f_e = 80\ cm + 4\ cm = 84\ cm$.', 'For an astronomical telescope in normal adjustment, the final image is formed at infinity. The angular magnification $M$ is given by $M = \frac{f_o}{f_e}$, where $f_o$ is the focal length of the objective lens and $f_e$ is the focal length of the eyepiece.<br>Given $M = 20$ and $f_o = 80\ cm$, we have $20 = \frac{80}{f_e} \implies f_e = 4\ cm$.<br>The distance between the objective lens and the eyepiece in normal adjustment is $L = f_o + f_e = 80\ cm + 4\ cm = 84\ cm$.', NULL, 'sanitized', 'v1', 5, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
