INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('5eee6825-364c-5aae-a5b2-0555429ed561', '192ba85b-45c0-5e6a-9440-9b77c29515ec', 11, '<p>Faraday''s law of electromagnetic induction is related to</p>', '<p>Faraday''s law of electromagnetic induction is related to</p>', NULL, 'Faraday''s law of electromagnetic induction (and specifically Lenz''s Law, which provides the direction of the induced e.m.f.) is a direct consequence of the law of conservation of energy. The mechanical work done in moving a magnet relative to a coil, for example, is converted into electrical energy.', 'Faraday''s law of electromagnetic induction (and specifically Lenz''s Law, which provides the direction of the induced e.m.f.) is a direct consequence of the law of conservation of energy. The mechanical work done in moving a magnet relative to a coil, for example, is converted into electrical energy.', NULL, 'sanitized', 'v1', 5, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
