INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('e41958ed-5d61-4273-97c3-f0fba987b3fe', 'bf9f2f99-ad9e-5e58-9a98-39c4d2da00c5', '2.4 V', '2.4 V', NULL, 'sanitized', 'v1', 4, 0);
INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('1ad071ee-cb02-5a96-8eb1-48c9d8e3044e', '192ba85b-45c0-5e6a-9440-9b77c29515ec', 19, '<p>A uniform rope of length $5.0\ m$ and mass $2.5\ kg$ hangs vertically from a rigid support. A block of mass $2.0\ kg$ is attached to the free end of the rope as shown in the figure. A transverse pulse of wavelength $2.0\ cm$ is produced at the lower end of the rope. What is the wavelength of the pulse when it reaches the top of the rope?</p>', '<p>A uniform rope of length $5.0\ m$ and mass $2.5\ kg$ hangs vertically from a rigid support. A block of mass $2.0\ kg$ is attached to the free end of the rope as shown in the figure. A transverse pulse of wavelength $2.0\ cm$ is produced at the lower end of the rope. What is the wavelength of the pulse when it reaches the top of the rope?</p>', NULL, 'The speed of a transverse wave in a rope is $v = \sqrt{\frac{T}{\mu}}$. Since the frequency $f$ remains constant, wavelength $\lambda \propto v$, therefore $\lambda \propto \sqrt{T}$.<br>At the lower end, the tension $T_1$ is due only to the block: $T_1 = 2.0\ kg \times 10\ m\ s^{-2} = 20\ N$.<br>At the top end, the tension $T_2$ is due to both the block and the rope: $T_2 = (2.0 + 2.5)\ kg \times 10\ m\ s^{-2} = 45\ N$.<br>The ratio of wavelengths is $\frac{\lambda_2}{\lambda_1} = \sqrt{\frac{T_2}{T_1}} = \sqrt{\frac{45}{20}} = \sqrt{2.25} = 1.5$.<br>$\lambda_2 = 1.5 \times 2.0\ cm = 3.0\ cm$.', 'The speed of a transverse wave in a rope is $v = \sqrt{\frac{T}{\mu}}$. Since the frequency $f$ remains constant, wavelength $\lambda \propto v$, therefore $\lambda \propto \sqrt{T}$.<br>At the lower end, the tension $T_1$ is due only to the block: $T_1 = 2.0\ kg \times 10\ m\ s^{-2} = 20\ N$.<br>At the top end, the tension $T_2$ is due to both the block and the rope: $T_2 = (2.0 + 2.5)\ kg \times 10\ m\ s^{-2} = 45\ N$.<br>The ratio of wavelengths is $\frac{\lambda_2}{\lambda_1} = \sqrt{\frac{T_2}{T_1}} = \sqrt{\frac{45}{20}} = \sqrt{2.25} = 1.5$.<br>$\lambda_2 = 1.5 \times 2.0\ cm = 3.0\ cm$.', NULL, 'sanitized', 'v1', 5, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
