INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('75c92622-9f9f-560a-9876-cf575b282dd6', '192ba85b-45c0-5e6a-9440-9b77c29515ec', 24, '<p>A current $I$ flows through a uniform metal wire which is maintained at a constant temperature. Which of the following graphs best represents the variation of power dissipation $P$ in the wire with current $I$ in the wire?</p>', '<p>A current $I$ flows through a uniform metal wire which is maintained at a constant temperature. Which of the following graphs best represents the variation of power dissipation $P$ in the wire with current $I$ in the wire?</p>', NULL, 'The power dissipated in a resistor is given by the equation $P = I^2R$.<br>Since the wire is maintained at a constant temperature, its resistance $R$ is constant.<br>Therefore, $P$ is directly proportional to the square of the current ($P \propto I^2$). The graph of $P$ against $I$ should be a parabola passing through the origin, opening upwards. Graph 4 correctly represents this parabolic relationship.', 'The power dissipated in a resistor is given by the equation $P = I^2R$.<br>Since the wire is maintained at a constant temperature, its resistance $R$ is constant.<br>Therefore, $P$ is directly proportional to the square of the current ($P \propto I^2$). The graph of $P$ against $I$ should be a parabola passing through the origin, opening upwards. Graph 4 correctly represents this parabolic relationship.', NULL, 'sanitized', 'v1', 5, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
