INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('544d498c-dad1-5acb-80a1-86948ab59eb3', '192ba85b-45c0-5e6a-9440-9b77c29515ec', 34, '<p>A set of parallel resistors and a set of series resistors are connected as shown in the figure. The resistance values of resistors may or may not be the same. Which of the following statements is always true?</p>', '<p>A set of parallel resistors and a set of series resistors are connected as shown in the figure. The resistance values of resistors may or may not be the same. Which of the following statements is always true?</p>', NULL, 'Let the equivalent resistance of the parallel group be $R_p$ and the series group be $R_{s1}, R_{s2}, R_{s3}$. If the two sets are in series with each other, the total equivalent resistance is $R_{eq} = R_p + R_{s1} + R_{s2} + \dots$<br>Since $R_p > 0$, the total resistance $R_{eq}$ is strictly greater than any individual series resistor ($R_{s1}$, $R_{s2}$, etc.). This holds true regardless of the specific resistance values.', 'Let the equivalent resistance of the parallel group be $R_p$ and the series group be $R_{s1}, R_{s2}, R_{s3}$. If the two sets are in series with each other, the total equivalent resistance is $R_{eq} = R_p + R_{s1} + R_{s2} + \dots$<br>Since $R_p > 0$, the total resistance $R_{eq}$ is strictly greater than any individual series resistor ($R_{s1}$, $R_{s2}$, etc.). This holds true regardless of the specific resistance values.', NULL, 'sanitized', 'v1', 5, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('3f0e45b3-b320-4320-b358-93cd668c6d67', '544d498c-dad1-5acb-80a1-86948ab59eb3', 'The current through each resistor in the set of parallel resistors is the same.', 'The current through each resistor in the set of parallel resistors is the same.', NULL, 'sanitized', 'v1', 0, 1);
