INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('786da06b-3bb0-4f8e-8257-19fd6effaa59', '544d498c-dad1-5acb-80a1-86948ab59eb3', 'The total resistance of the entire network is greater than the resistance of any individual resistor in the set of series resistors.', 'The total resistance of the entire network is greater than the resistance of any individual resistor in the set of series resistors.', NULL, 'sanitized', 'v1', 2, 0);
