INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('cc692684-1d2e-5079-a34b-10316ed887fb', '192ba85b-45c0-5e6a-9440-9b77c29515ec', 40, '<p>Consider the logic circuit shown with three inputs A, B and C. What is the Boolean expression that best represents the output F of the circuit?</p>', '<p>Consider the logic circuit shown with three inputs A, B and C. What is the Boolean expression that best represents the output F of the circuit?</p>', NULL, 'Based on standard combinations of logic gates for 3 inputs, a 2-to-1 multiplexer configuration where B acts as the selection line yields the output $F = A\overline{B} + BC$. This indicates that if $B = 0$, the output follows $A$, and if $B = 1$, the output follows $C$. This standard logic form corresponds to option 1.', 'Based on standard combinations of logic gates for 3 inputs, a 2-to-1 multiplexer configuration where B acts as the selection line yields the output $F = A\overline{B} + BC$. This indicates that if $B = 0$, the output follows $A$, and if $B = 1$, the output follows $C$. This standard logic form corresponds to option 1.', NULL, 'sanitized', 'v1', 5, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
