INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('276a4ade-0205-503d-acc8-7393ca9b99c5', '192ba85b-45c0-5e6a-9440-9b77c29515ec', 44, '<p>For a satellite moving in a circular path around the earth the kinetic energy, gravitational potential energy and total energy are given by $K$, $V$ and $E$ respectively. Which of the following relationships is true?</p>', '<p>For a satellite moving in a circular path around the earth the kinetic energy, gravitational potential energy and total energy are given by $K$, $V$ and $E$ respectively. Which of the following relationships is true?</p>', NULL, 'For a satellite in a circular orbit of radius $r$, the gravitational force provides the centripetal force: $\frac{GMm}{r^2} = \frac{mv^2}{r} \implies mv^2 = \frac{GMm}{r}$.<br>Kinetic Energy $K = \frac{1}{2}mv^2 = \frac{GMm}{2r}$.<br>Potential Energy $V = -\frac{GMm}{r} = -2K$.<br>Total Energy $E = K + V = K - 2K = -K$.<br>Thus, $E = -K$ is the correct relationship.', 'For a satellite in a circular orbit of radius $r$, the gravitational force provides the centripetal force: $\frac{GMm}{r^2} = \frac{mv^2}{r} \implies mv^2 = \frac{GMm}{r}$.<br>Kinetic Energy $K = \frac{1}{2}mv^2 = \frac{GMm}{2r}$.<br>Potential Energy $V = -\frac{GMm}{r} = -2K$.<br>Total Energy $E = K + V = K - 2K = -K$.<br>Thus, $E = -K$ is the correct relationship.', NULL, 'sanitized', 'v1', 5, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('6a217de9-7c00-483b-a437-94686faaca25', '276a4ade-0205-503d-acc8-7393ca9b99c5', '$E=-K$', '$E=-K$', NULL, 'sanitized', 'v1', 0, 1);
