INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('4b77c27f-843f-46ad-8899-79a5596fdaab', '156c0234-f852-5be9-9fce-beb9c0309b03', '$\frac{\mu m}{1+\mu}$', '$\frac{\mu m}{1+\mu}$', NULL, 'sanitized', 'v1', 2, 0);
