INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('b34ec727-da2c-42c8-990b-f4e05f5de856', '051417a6-c0b7-583a-b91f-d41934503164', 'කුමාරසිංහ, ජයකොඩි, සරච්චන්ද්‍ර, නන්දිමිත්‍ර', 'කුමාරසිංහ, ජයකොඩි, සරච්චන්ද්‍ර, නන්දිමිත්‍ර', NULL, 'sanitized', 'v1', 2, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('e4bd6a61-cb8c-4f42-ad26-96d151fe3e4a', '051417a6-c0b7-583a-b91f-d41934503164', 'කරුණාසේන, දයාසේන, කරුණාරත්න, සුනේත්‍රා', 'කරුණාසේන, දයාසේන, කරුණාරත්න, සුනේත්‍රා', NULL, 'sanitized', 'v1', 3, 0);
INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('8f5aeac2-37fe-52a0-b4ea-0a792e6407d3', '2254a2a2-0560-55cf-a91c-f733a7db26af', 11, '<p>අනුක්ත නාම පද පමණක් යෙදී ඇති වරණය තෝරන්න.</p>', '<p>අනුක්ත නාම පද පමණක් යෙදී ඇති වරණය තෝරන්න.</p>', NULL, 'අනුක්ත නාම පද යනු වාක්‍යයක කර්මය ආදිය ලෙස යෙදෙන පද වේ. ''ඌරකු, වැඳිරියක, අංගනාවන්, අහිංසකයකු'' යන සියල්ල අනුක්ත පද වේ. අනෙක් වරණවල උක්ත පද (උදා: නාගරිකයෙක්, වැද්දෙක්, ලේඛිකාවක්) අඩංගු ය.', 'අනුක්ත නාම පද යනු වාක්‍යයක කර්මය ආදිය ලෙස යෙදෙන පද වේ. ''ඌරකු, වැඳිරියක, අංගනාවන්, අහිංසකයකු'' යන සියල්ල අනුක්ත පද වේ. අනෙක් වරණවල උක්ත පද (උදා: නාගරිකයෙක්, වැද්දෙක්, ලේඛිකාවක්) අඩංගු ය.', NULL, 'sanitized', 'v1', 4, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
