INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('d4de47fe-d32c-4eff-86d9-777ed967b945', '2d086ecf-9f01-5c1a-9c01-496b3775e6fc', 'මිශ්‍ර ක්‍රියා - සිනාසිසී, තරමින්, යමින්, බාමින්', 'මිශ්‍ර ක්‍රියා - සිනාසිසී, තරමින්, යමින්, බාමින්', NULL, 'sanitized', 'v1', 2, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('a6f762ea-a437-4c91-af01-d89c6e4dfc49', '2d086ecf-9f01-5c1a-9c01-496b3775e6fc', 'පර රූප සන්ධිය - ගොක්කොළ, හද්දවස, අස්සන, ළිබ්බොක්ක', 'පර රූප සන්ධිය - ගොක්කොළ, හද්දවස, අස්සන, ළිබ්බොක්ක', NULL, 'sanitized', 'v1', 3, 0);
INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('139be5cb-f68a-5ce9-99d6-70a0ec3d7883', '2254a2a2-0560-55cf-a91c-f733a7db26af', 16, '<p>ප්‍රයෝජ්‍ය ක්‍රියාවක් යෙදී ඇති වාක්‍යය කුමක්ද?</p>', '<p>ප්‍රයෝජ්‍ය ක්‍රියාවක් යෙදී ඇති වාක්‍යය කුමක්ද?</p>', NULL, 'කර්තෘ විසින් තවත් අයකු ලවා ක්‍රියාවක් කරවීම ප්‍රයෝජ්‍ය ක්‍රියාවකි. අහිකුණ්ඨිකයා තමා නොනටා, රිළවා ලවා නැටවීමේ ක්‍රියාව සිදුකරන බැවින් ''නටවයි'' යනු ප්‍රයෝජ්‍ය ක්‍රියාවකි.', 'කර්තෘ විසින් තවත් අයකු ලවා ක්‍රියාවක් කරවීම ප්‍රයෝජ්‍ය ක්‍රියාවකි. අහිකුණ්ඨිකයා තමා නොනටා, රිළවා ලවා නැටවීමේ ක්‍රියාව සිදුකරන බැවින් ''නටවයි'' යනු ප්‍රයෝජ්‍ය ක්‍රියාවකි.', NULL, 'sanitized', 'v1', 4, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('bc1d092c-5243-4d52-8ccf-4012cb137116', '139be5cb-f68a-5ce9-99d6-70a0ec3d7883', 'ඉන්ද්‍රජාලිකයා සිත්තමක් මවයි.', 'ඉන්ද්‍රජාලිකයා සිත්තමක් මවයි.', NULL, 'sanitized', 'v1', 0, 1);
