INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('9957ee78-8a17-56a6-aad3-3669e3ef3268', '2254a2a2-0560-55cf-a91c-f733a7db26af', 25, '<p>පහත දැක්වෙන වාක්‍ය අතුරෙන් මනා පද ගැළපීමෙන් යුක්ත, අර්ථාන්විත වාක්‍යය තෝරන්න.</p>', '<p>පහත දැක්වෙන වාක්‍ය අතුරෙන් මනා පද ගැළපීමෙන් යුක්ත, අර්ථාන්විත වාක්‍යය තෝරන්න.</p>', NULL, 'ව්‍යාකරණානුකූලව හා අර්ථවත් ලෙස නිවැරදිව පද ගළපා ඇත්තේ 3 වන වාක්‍යයේ ය.', 'ව්‍යාකරණානුකූලව හා අර්ථවත් ලෙස නිවැරදිව පද ගළපා ඇත්තේ 3 වන වාක්‍යයේ ය.', NULL, 'sanitized', 'v1', 4, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('772aff50-fa55-4cd4-a636-bb545fa92be1', '9957ee78-8a17-56a6-aad3-3669e3ef3268', 'නගර සභාවෙහි මුඛ්‍ය කාර්යය කුණු ඉවත් කිරීම පිණිස ය.', 'නගර සභාවෙහි මුඛ්‍ය කාර්යය කුණු ඉවත් කිරීම පිණිස ය.', NULL, 'sanitized', 'v1', 0, 1);
