INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('02b330d9-78a7-49d3-9adf-f90955665263', '9957ee78-8a17-56a6-aad3-3669e3ef3268', 'ගිරි දුර්ගය පසු කිරීමට පල්ලමක් බැසිය යුතුමය.', 'ගිරි දුර්ගය පසු කිරීමට පල්ලමක් බැසිය යුතුමය.', NULL, 'sanitized', 'v1', 3, 0);
INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('681bc5d8-ef0b-576c-8953-4495636a2545', '2254a2a2-0560-55cf-a91c-f733a7db26af', 26, '<p>අංක 26, 27 ප්‍රශ්න යටතේ දක්වා ඇති අදහසට වඩාත් ම ගැළපෙන ප්‍රස්තාව පිරුළ අන්තර්ගත වරණය තෝරන්න.<br><br>යමක් අවිනිශ්චිත ස්වරූපයෙන් පැවතීම</p>', '<p>අංක 26, 27 ප්‍රශ්න යටතේ දක්වා ඇති අදහසට වඩාත් ම ගැළපෙන ප්‍රස්තාව පිරුළ අන්තර්ගත වරණය තෝරන්න.<br><br>යමක් අවිනිශ්චිත ස්වරූපයෙන් පැවතීම</p>', NULL, '''මඩේ හිටවපු ඉන්න වගේ'' යන පිරුළෙන් අදහස් වන්නේ ස්ථිරත්වයක් නොමැතිව, එහාට මෙහාට වැනෙන අවිනිශ්චිත ස්වරූපයකි.', '''මඩේ හිටවපු ඉන්න වගේ'' යන පිරුළෙන් අදහස් වන්නේ ස්ථිරත්වයක් නොමැතිව, එහාට මෙහාට වැනෙන අවිනිශ්චිත ස්වරූපයකි.', NULL, 'sanitized', 'v1', 4, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('08e6f30b-7819-498e-872b-6b7eacc15e93', '681bc5d8-ef0b-576c-8953-4495636a2545', 'එළිපත්ත උඩ ඉන්න බළලා වගේ.', 'එළිපත්ත උඩ ඉන්න බළලා වගේ.', NULL, 'sanitized', 'v1', 0, 1);
