INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('d0bb2296-51c5-41e9-928d-fbdff692633d', 'a5e9d778-79a1-5b54-9e5e-1564240bbd79', 'රටට, ජනතාවට හිතැති යහපත් පාලකයෙක් පහළ වේවා!', 'රටට, ජනතාවට හිතැති යහපත් පාලකයෙක් පහළ වේවා!', NULL, 'sanitized', 'v1', 3, 0);
