INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('5a064763-bc22-4c42-b41b-2ac69431a925', '753dcb7c-f7fb-51e7-a600-dc68e6c111e8', 'ශාස්ත්‍රීය හා වෘත්තීය විෂයධාරා වලින් යුත් මධ්‍ය විද්‍යාල රැසක් පිහිටුවීම', 'ශාස්ත්‍රීය හා වෘත්තීය විෂයධාරා වලින් යුත් මධ්‍ය විද්‍යාල රැසක් පිහිටුවීම', NULL, 'sanitized', 'v1', 2, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('82e0ef87-3993-4c82-b96d-fd536e327f31', '753dcb7c-f7fb-51e7-a600-dc68e6c111e8', 'ඉංග්‍රීසි මාධ්‍යයෙන් අධ්‍යාපනය ලැබීම අනිවාර්ය කිරීම', 'ඉංග්‍රීසි මාධ්‍යයෙන් අධ්‍යාපනය ලැබීම අනිවාර්ය කිරීම', NULL, 'sanitized', 'v1', 3, 0);
INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('0450d9cd-d822-5006-beed-7ee72a744dea', '2254a2a2-0560-55cf-a91c-f733a7db26af', 34, '<p>වෙර වීරිය ඇතත් හිතේ<br>පියකරු බව ඇතත් වතේ<br>දහදිය නොම සැලෙන ගතේ<br>ඔබ පොළවට බරකි පුතේ<br><br>යන පද්‍යයේ අදහස නිවැරදි ව දැක්වෙන වරණය තෝරන්න.</p>', '<p>වෙර වීරිය ඇතත් හිතේ<br>පියකරු බව ඇතත් වතේ<br>දහදිය නොම සැලෙන ගතේ<br>ඔබ පොළවට බරකි පුතේ<br><br>යන පද්‍යයේ අදහස නිවැරදි ව දැක්වෙන වරණය තෝරන්න.</p>', NULL, 'සිතේ ධෛර්යය සහ මුහුණේ ලස්සන තිබුණත්, වෙහෙසී වැඩ කර දහදිය නොහෙළන්නේ නම් ඔහු මහපොළොවට බරක් වන බව පද්‍යයෙන් කියැවේ.', 'සිතේ ධෛර්යය සහ මුහුණේ ලස්සන තිබුණත්, වෙහෙසී වැඩ කර දහදිය නොහෙළන්නේ නම් ඔහු මහපොළොවට බරක් වන බව පද්‍යයෙන් කියැවේ.', NULL, 'sanitized', 'v1', 4, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('b511b073-bef6-4b75-911d-8a483d36e631', '0450d9cd-d822-5006-beed-7ee72a744dea', 'ශරීර ශක්තියෙන් හා මුහුණේ පැහැපත් බවින් යුතු ව මහ පොළොවට බරක් නොවී රට වෙනුවෙන් ශ්‍රම දායකත්වය ලබාදිය යුතු බව', 'ශරීර ශක්තියෙන් හා මුහුණේ පැහැපත් බවින් යුතු ව මහ පොළොවට බරක් නොවී රට වෙනුවෙන් ශ්‍රම දායකත්වය ලබාදිය යුතු බව', NULL, 'sanitized', 'v1', 0, 1);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('bc4b817c-fe71-44ef-8eef-fa92afd1d299', '0450d9cd-d822-5006-beed-7ee72a744dea', 'ශරීර ශක්තිය හා මුහුණේ පැහැපත් බව තිබුණ ද රට වෙනුවෙන් ශ්‍රම දායකත්වයක් සපයන්නේ නැති නම් ඔහුගෙන් පලක් නැති බව', 'ශරීර ශක්තිය හා මුහුණේ පැහැපත් බව තිබුණ ද රට වෙනුවෙන් ශ්‍රම දායකත්වයක් සපයන්නේ නැති නම් ඔහුගෙන් පලක් නැති බව', NULL, 'sanitized', 'v1', 1, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('1f1a6e7b-169a-498e-809f-3778b0deb6a9', '0450d9cd-d822-5006-beed-7ee72a744dea', 'රට වෙනුවෙන් ශ්‍රමය වැය කිරීම අනිවාර්යයෙන් කළ යුතු වුවත් ශරීර ශක්තිය හා මුහුණේ පැහැපත් බව රැක ගත යුතු බව', 'රට වෙනුවෙන් ශ්‍රමය වැය කිරීම අනිවාර්යයෙන් කළ යුතු වුවත් ශරීර ශක්තිය හා මුහුණේ පැහැපත් බව රැක ගත යුතු බව', NULL, 'sanitized', 'v1', 2, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('d6e44ce1-fb13-4870-8598-b60513c704ca', '0450d9cd-d822-5006-beed-7ee72a744dea', 'මහ පොළොවට බරක් වන්නේ ශරීර ශක්තිය හා මුහුණේ පැහැපත් බව රැක ගනිමින් ශ්‍රම දායකත්වය සැපයීම නොකළ විට බව', 'මහ පොළොවට බරක් වන්නේ ශරීර ශක්තිය හා මුහුණේ පැහැපත් බව රැක ගනිමින් ශ්‍රම දායකත්වය සැපයීම නොකළ විට බව', NULL, 'sanitized', 'v1', 3, 0);
INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('d69b7825-b5b5-5667-911e-779fce9250c9', '2254a2a2-0560-55cf-a91c-f733a7db26af', 35, '<p>හුණුවටයේ කතාව නාට්‍යයේ ඇතුළත්,<br><br>''අප්ප උඹේ හොර දෙටුවා<br>අම්ම හරිම කුනකටුවා<br>ඒ හින්දා පුතේ උඹට<br>මුළු ලෝකෙම දණ නමාවී''<br><br>යන ගීය කියන්නේ,</p>', '<p>හුණුවටයේ කතාව නාට්‍යයේ ඇතුළත්,<br><br>''අප්ප උඹේ හොර දෙටුවා<br>අම්ම හරිම කුනකටුවා<br>ඒ හින්දා පුතේ උඹට<br>මුළු ලෝකෙම දණ නමාවී''<br><br>යන ගීය කියන්නේ,</p>', NULL, 'මෙම ගීතය ගායනා කරන්නේ හුණුවටයේ කතාව නාට්‍යයේ ප්‍රධාන චරිතයක් වන ගෲෂා විසිනි.', 'මෙම ගීතය ගායනා කරන්නේ හුණුවටයේ කතාව නාට්‍යයේ ප්‍රධාන චරිතයක් වන ගෲෂා විසිනි.', NULL, 'sanitized', 'v1', 4, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
