INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('a72a1524-d0f1-5ebc-a183-3f1de5cd9de5', '23134ed2-6633-5a6f-b7d7-7eddebe8b24d', 7, '<p>ද්විමය $10001000_2$ ට තුල්‍ය දශමය සංඛ්‍යාව කුමක්ද?</p>', '<p>ද්විමය $10001000_2$ ට තුල්‍ය දශමය සංඛ්‍යාව කුමක්ද?</p>', NULL, '$10001000_2 = (1 \times 128) + (0 \times 64) + (0 \times 32) + (0 \times 16) + (1 \times 8) + (0 \times 4) + (0 \times 2) + (0 \times 1) = 128 + 8 = 136_{10}$ වේ.', '$10001000_2 = (1 \times 128) + (0 \times 64) + (0 \times 32) + (0 \times 16) + (1 \times 8) + (0 \times 4) + (0 \times 2) + (0 \times 1) = 128 + 8 = 136_{10}$ වේ.', NULL, 'sanitized', 'v1', 4, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
