INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('08bfab45-6eaa-5ff3-aeb3-61f2a669faab', '23134ed2-6633-5a6f-b7d7-7eddebe8b24d', 8, '<p>අෂ්ටමය $1572_8$ ට තුල්‍ය ෂඩ් දශමය සංඛ්‍යාව කුමක්ද?</p>', '<p>අෂ්ටමය $1572_8$ ට තුල්‍ය ෂඩ් දශමය සංඛ්‍යාව කුමක්ද?</p>', NULL, 'පළමුව අෂ්ටක සංඛ්‍යාව ද්විමයට හරවමු: $1 \rightarrow 001$, $5 \rightarrow 101$, $7 \rightarrow 111$, $2 \rightarrow 010$. එනම් $001101111010_2$.<br>ඉන්පසු එය බිටු 4 කාණ්ඩ වලට වෙන් කරමු: $0011$ $(3)$, $0111$ $(7)$, $1010$ $(A)$. එනම් පිළිතුර $37A_{16}$ වේ.', 'පළමුව අෂ්ටක සංඛ්‍යාව ද්විමයට හරවමු: $1 \rightarrow 001$, $5 \rightarrow 101$, $7 \rightarrow 111$, $2 \rightarrow 010$. එනම් $001101111010_2$.<br>ඉන්පසු එය බිටු 4 කාණ්ඩ වලට වෙන් කරමු: $0011$ $(3)$, $0111$ $(7)$, $1010$ $(A)$. එනම් පිළිතුර $37A_{16}$ වේ.', NULL, 'sanitized', 'v1', 4, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
