INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('d11ed2cf-f71f-58b6-ba70-4c1b5d7e9247', '23134ed2-6633-5a6f-b7d7-7eddebe8b24d', 9, '<p>ටෙරා බයිට 1 ක් (1 TB) සමාන වන්නේ, කුමක්ද?</p>', '<p>ටෙරා බයිට 1 ක් (1 TB) සමාන වන්නේ, කුමක්ද?</p>', NULL, '$1 TB = 1024 GB$<br>$1 GB = 1024 MB$<br>$1 MB = 1024 KB$<br>එබැවින් $1 TB = 1024 \times 1024 \times 1024$ KB වේ.', '$1 TB = 1024 GB$<br>$1 GB = 1024 MB$<br>$1 MB = 1024 KB$<br>එබැවින් $1 TB = 1024 \times 1024 \times 1024$ KB වේ.', NULL, 'sanitized', 'v1', 4, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
