INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('12e22095-d23d-5c37-9a28-6eff6068243f', '23134ed2-6633-5a6f-b7d7-7eddebe8b24d', 27, '<p>පැස්කල්හි කාරක ප්‍රමුඛතාව (operator precedence) සැලකූ විට $4-1^{*}3+5$ ප්‍රකාශනයේ ප්‍රතිඵලය කුමක් වේ ද?</p>', '<p>පැස්කල්හි කාරක ප්‍රමුඛතාව (operator precedence) සැලකූ විට $4-1^{*}3+5$ ප්‍රකාශනයේ ප්‍රතිඵලය කුමක් වේ ද?</p>', NULL, 'BODMAS හෝ සාමාන්‍ය ගණිත කර්ම ප්‍රමුඛතාව අනුව පළමුව ගුණ කිරීම සිදු කළ යුතුය.<br>$4 - (1 \times 3) + 5$<br>$= 4 - 3 + 5$<br>$= 1 + 5 = 6$', 'BODMAS හෝ සාමාන්‍ය ගණිත කර්ම ප්‍රමුඛතාව අනුව පළමුව ගුණ කිරීම සිදු කළ යුතුය.<br>$4 - (1 \times 3) + 5$<br>$= 4 - 3 + 5$<br>$= 1 + 5 = 6$', NULL, 'sanitized', 'v1', 4, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
