INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('ba3c0cd7-1cbf-5ce0-8957-c2b554b301b7', '29f5bbf4-11d0-52b2-9c36-80bd6211f940', 1, '<p>සෛලයක න්‍යෂ්ටිය පිළිබඳ පහත සඳහන් ප්‍රකාශ අතුරෙන් නිවැරදි වන්නේ කුමක් ද?</p>', '<p>සෛලයක න්‍යෂ්ටිය පිළිබඳ පහත සඳහන් ප්‍රකාශ අතුරෙන් නිවැරදි වන්නේ කුමක් ද?</p>', NULL, 'න්‍යෂ්ටි ආවරණයේ ඇති සිදුරු සංකීර්ණය (Pore complex) මගින් ප්‍රෝටීන හා RNA වැනි මහා අණු න්‍යෂ්ටියට ඇතුළුවීම හා පිටවීම යාමනය කරයි. න්‍යෂ්ටි තලාව පවතින්නේ ඇතුළත පටලයේය. ඇතුළත සහ පිටත පටල අතර පරතරය $20-40 nm$ පමණ වේ.', 'න්‍යෂ්ටි ආවරණයේ ඇති සිදුරු සංකීර්ණය (Pore complex) මගින් ප්‍රෝටීන හා RNA වැනි මහා අණු න්‍යෂ්ටියට ඇතුළුවීම හා පිටවීම යාමනය කරයි. න්‍යෂ්ටි තලාව පවතින්නේ ඇතුළත පටලයේය. ඇතුළත සහ පිටත පටල අතර පරතරය $20-40 nm$ පමණ වේ.', NULL, 'sanitized', 'v1', 5, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('6db77a41-fa24-494d-8300-6a717ab2960f', 'ba3c0cd7-1cbf-5ce0-8957-c2b554b301b7', 'න්‍යෂ්ටි ආවරණයේ පිටත ආස්තරණය කරන ප්‍රෝටීන සූත්‍රිකා වලින් න්‍යෂ්ටි තලාව තැනී ඇත.', 'න්‍යෂ්ටි ආවරණයේ පිටත ආස්තරණය කරන ප්‍රෝටීන සූත්‍රිකා වලින් න්‍යෂ්ටි තලාව තැනී ඇත.', NULL, 'sanitized', 'v1', 0, 1);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('126fb6b9-2f22-472a-9a93-88ac1956641f', 'ba3c0cd7-1cbf-5ce0-8957-c2b554b301b7', 'න්‍යෂ්ටි ආවරණයේ ඇතුළත සහ පිටත පටල වෙන් වී ඇත්තේ $20-40 \mu m$ ක් වූ අවකාශයකිනි.', 'න්‍යෂ්ටි ආවරණයේ ඇතුළත සහ පිටත පටල වෙන් වී ඇත්තේ $20-40 \mu m$ ක් වූ අවකාශයකිනි.', NULL, 'sanitized', 'v1', 1, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('27271876-e954-4801-b46f-6d831227ab6f', 'ba3c0cd7-1cbf-5ce0-8957-c2b554b301b7', 'ද්‍රව්‍ය ඇතුළු වීම සහ පිට වීම යාමනය කිරීම සඳහා සිදුරු සංකීර්ණයක් න්‍යෂ්ටි ආවරණයේ ඇත.', 'ද්‍රව්‍ය ඇතුළු වීම සහ පිට වීම යාමනය කිරීම සඳහා සිදුරු සංකීර්ණයක් න්‍යෂ්ටි ආවරණයේ ඇත.', NULL, 'sanitized', 'v1', 2, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('88427a9f-b0ab-48b6-9d95-8d0b8a3148a5', 'ba3c0cd7-1cbf-5ce0-8957-c2b554b301b7', 'න්‍යෂ්ටිකාව න්‍යෂ්ටි තලාව තුළ ගිලී ඇත.', 'න්‍යෂ්ටිකාව න්‍යෂ්ටි තලාව තුළ ගිලී ඇත.', NULL, 'sanitized', 'v1', 3, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('2dd4cde9-e6b5-4b70-bea9-925d7e269043', 'ba3c0cd7-1cbf-5ce0-8957-c2b554b301b7', 'විභාජනය නොවන සෛල තුළ ක්‍රොමැටින් ඇත්තේ තදින් දඟර ගැසුනු ගොනුවක් ලෙස ය.', 'විභාජනය නොවන සෛල තුළ ක්‍රොමැටින් ඇත්තේ තදින් දඟර ගැසුනු ගොනුවක් ලෙස ය.', NULL, 'sanitized', 'v1', 4, 0);
INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('1201f57e-f21f-5ad8-915e-15e848d3f20c', '29f5bbf4-11d0-52b2-9c36-80bd6211f940', 2, '<p>පහත සඳහන් කුමන ක්ෂේත්‍ර වල පරීක්ෂණ සහ නිරීක්ෂණ ප්‍රථම ජීවී සෛල බිහිවීම සඳහා සාක්ෂි සපයා තිබේ ද?<br><br>A - ජීව විද්‍යාව<br>B - රසායන විද්‍යාව<br>C - භූගර්භ විද්‍යාව<br>D - භෞතික විද්‍යාව</p>', '<p>පහත සඳහන් කුමන ක්ෂේත්‍ර වල පරීක්ෂණ සහ නිරීක්ෂණ ප්‍රථම ජීවී සෛල බිහිවීම සඳහා සාක්ෂි සපයා තිබේ ද?<br><br>A - ජීව විද්‍යාව<br>B - රසායන විද්‍යාව<br>C - භූගර්භ විද්‍යාව<br>D - භෞතික විද්‍යාව</p>', NULL, 'ප්‍රථම ජීවී සෛල සම්භවය පිළිබඳ විද්‍යාත්මක සාක්ෂි ප්‍රධාන වශයෙන් ලැබෙන්නේ රසායනික පරිණාමය (රසායන විද්‍යාව), පොසිල වාර්තා (භූගර්භ විද්‍යාව) සහ විකිරණශීලී කාලනිර්ණය (භෞතික විද්‍යාව) මගිනි.', 'ප්‍රථම ජීවී සෛල සම්භවය පිළිබඳ විද්‍යාත්මක සාක්ෂි ප්‍රධාන වශයෙන් ලැබෙන්නේ රසායනික පරිණාමය (රසායන විද්‍යාව), පොසිල වාර්තා (භූගර්භ විද්‍යාව) සහ විකිරණශීලී කාලනිර්ණය (භෞතික විද්‍යාව) මගිනි.', NULL, 'sanitized', 'v1', 5, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
