INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('19b6e26f-49ff-513b-8b95-f63cc3770340', '29f5bbf4-11d0-52b2-9c36-80bd6211f940', 3, '<p>ජීවීන්ගේ ලක්ෂණ පිළිබඳ නිවැරදි ප්‍රකාශය තෝරන්න.</p>', '<p>ජීවීන්ගේ ලක්ෂණ පිළිබඳ නිවැරදි ප්‍රකාශය තෝරන්න.</p>', NULL, 'ජීවීන්ගේ චලනය සඳහා උද්දීප්‍යතාව සහ සමායෝජනය යන ලක්ෂණ දෙකම මූලිකවම දායක වේ. වර්ධනය යනු අප්‍රතිවර්ත්‍ය ලෙස සිදුවන වියළි ස්කන්ධයේ වැඩිවීම වන අතර, දී ඇති 5 වන ප්‍රකාශයේ ''අප්‍රතිවර්ත්‍ය'' යන පදය අඩු බැවින් එය නිශ්චිතවම නිවැරදි නොවේ.', 'ජීවීන්ගේ චලනය සඳහා උද්දීප්‍යතාව සහ සමායෝජනය යන ලක්ෂණ දෙකම මූලිකවම දායක වේ. වර්ධනය යනු අප්‍රතිවර්ත්‍ය ලෙස සිදුවන වියළි ස්කන්ධයේ වැඩිවීම වන අතර, දී ඇති 5 වන ප්‍රකාශයේ ''අප්‍රතිවර්ත්‍ය'' යන පදය අඩු බැවින් එය නිශ්චිතවම නිවැරදි නොවේ.', NULL, 'sanitized', 'v1', 5, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('fa67dc0f-0791-473d-a849-d58b69c012d8', '19b6e26f-49ff-513b-8b95-f63cc3770340', 'විකසනය යනු ජීවියකුගේ ජිවිත කාලය තුළ සිදු වන වෙනස්වීම් ය.', 'විකසනය යනු ජීවියකුගේ ජිවිත කාලය තුළ සිදු වන වෙනස්වීම් ය.', NULL, 'sanitized', 'v1', 0, 1);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('68f8c6fa-0b82-4bb4-a8e0-4bb2139a6303', '19b6e26f-49ff-513b-8b95-f63cc3770340', 'පරිණාමය යනු ප්‍රවේණික විකරණවලට අනුකූලව ජීවියකු තම ජිවිත කාලය තුළ වෙනස් වීමයි.', 'පරිණාමය යනු ප්‍රවේණික විකරණවලට අනුකූලව ජීවියකු තම ජිවිත කාලය තුළ වෙනස් වීමයි.', NULL, 'sanitized', 'v1', 1, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('2f036249-9668-496b-b0fc-03b40e837b23', '19b6e26f-49ff-513b-8b95-f63cc3770340', 'පරිවෘත්තිය යනු ජීවියකු තුළ සිදුවන ශක්තිය වැය වන සියලු ම රසායනික ක්‍රියාවන්ගේ සමස්තයයි.', 'පරිවෘත්තිය යනු ජීවියකු තුළ සිදුවන ශක්තිය වැය වන සියලු ම රසායනික ක්‍රියාවන්ගේ සමස්තයයි.', NULL, 'sanitized', 'v1', 2, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('9a88d6e9-6f7d-4eaa-9e85-9601b4bef93b', '19b6e26f-49ff-513b-8b95-f63cc3770340', 'උද්දීප්‍යතාව සහ සමායෝජනය යන දෙකම ජීවීන්ගේ චලනය සඳහා අවශ්‍ය ය.', 'උද්දීප්‍යතාව සහ සමායෝජනය යන දෙකම ජීවීන්ගේ චලනය සඳහා අවශ්‍ය ය.', NULL, 'sanitized', 'v1', 3, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('3c05a399-831c-409f-8e46-ebb6f763e244', '19b6e26f-49ff-513b-8b95-f63cc3770340', 'වර්ධනය යනු ජීවියකුගේ වියළි ස්කන්ධයේ වැඩිවීමයි.', 'වර්ධනය යනු ජීවියකුගේ වියළි ස්කන්ධයේ වැඩිවීමයි.', NULL, 'sanitized', 'v1', 4, 0);
INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('2604d8ae-4698-5366-997b-0bc47b123d74', '29f5bbf4-11d0-52b2-9c36-80bd6211f940', 4, '<p>RNA වර්ග සහ ඒවායේ ලක්ෂණ පිළිබඳ පහත සඳහන් සංකලන අතුරෙන් නිවැරදි වන්නේ කුමක්ද? / කුමන ඒවා ද?<br><br>RNA වර්ගය<br>A - mRNA<br>B - tRNA<br>C - rRNA<br><br>ලක්ෂණ<br>න්‍යෂ්ටි ප්ලාස්මයේ සිට ප්‍රෝටීන සංශ්ලේෂණය සිදුවන ස්ථානයට ප්‍රවේණික තොරතුරු පරිවහනය කරයි; රේඛීය අණුවකි.<br>ප්‍රෝටීන සංශ්ලේෂණය සිදුවන ස්ථානයට ඇමයිනෝ අම්ල පරිවහනය කරයි; සංකීර්ණ අක්‍රමවත් අණුවකි.<br>පොලිපෙප්ටයිඩ දාම සෑදීම සඳහා ස්ථානය සපයයි; පුඩු තුනක් සහිත අණුවකි.</p>', '<p>RNA වර්ග සහ ඒවායේ ලක්ෂණ පිළිබඳ පහත සඳහන් සංකලන අතුරෙන් නිවැරදි වන්නේ කුමක්ද? / කුමන ඒවා ද?<br><br>RNA වර්ගය<br>A - mRNA<br>B - tRNA<br>C - rRNA<br><br>ලක්ෂණ<br>න්‍යෂ්ටි ප්ලාස්මයේ සිට ප්‍රෝටීන සංශ්ලේෂණය සිදුවන ස්ථානයට ප්‍රවේණික තොරතුරු පරිවහනය කරයි; රේඛීය අණුවකි.<br>ප්‍රෝටීන සංශ්ලේෂණය සිදුවන ස්ථානයට ඇමයිනෝ අම්ල පරිවහනය කරයි; සංකීර්ණ අක්‍රමවත් අණුවකි.<br>පොලිපෙප්ටයිඩ දාම සෑදීම සඳහා ස්ථානය සපයයි; පුඩු තුනක් සහිත අණුවකි.</p>', NULL, 'mRNA යනු රේඛීය අණුවක් වන අතර එය න්‍යෂ්ටියේ සිට රයිබොසෝම වෙත ප්‍රවේණික තොරතුරු ගෙන යයි (A නිවැරදිය). tRNA යනු ක්ලෝවර් පත්‍රයක හැඩය (පුඩු 3ක්) ඇති අණුවක් වන අතර rRNA යනු සංකීර්ණ අක්‍රමවත් හැඩයක් ඇති අණුවක් බැවින් B සහ C යන ප්‍රකාශවල ලක්ෂණ මාරු වී ඇත.', 'mRNA යනු රේඛීය අණුවක් වන අතර එය න්‍යෂ්ටියේ සිට රයිබොසෝම වෙත ප්‍රවේණික තොරතුරු ගෙන යයි (A නිවැරදිය). tRNA යනු ක්ලෝවර් පත්‍රයක හැඩය (පුඩු 3ක්) ඇති අණුවක් වන අතර rRNA යනු සංකීර්ණ අක්‍රමවත් හැඩයක් ඇති අණුවක් බැවින් B සහ C යන ප්‍රකාශවල ලක්ෂණ මාරු වී ඇත.', NULL, 'sanitized', 'v1', 5, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = e