INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('cfd1345f-8825-4324-9430-2f2aee12219e', '694d6b42-d45b-58d4-92a2-7b9f0e690200', 'තරඟකාරී නොවන නිශේධක එන්සයිමයේ සක්‍රිය ස්ථානයට බැඳේ.', 'තරඟකාරී නොවන නිශේධක එන්සයිමයේ සක්‍රිය ස්ථානයට බැඳේ.', NULL, 'sanitized', 'v1', 4, 0);
INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('c9622b98-fcdd-5c3c-aa9c-9018daa27458', '29f5bbf4-11d0-52b2-9c36-80bd6211f940', 8, '<p>ප්‍රභාපද්ධති පිළිබඳ පහත සඳහන් ප්‍රකාශ අතුරෙන් නිවැරදි වන්නේ කුමක්ද?</p>', '<p>ප්‍රභාපද්ධති පිළිබඳ පහත සඳහන් ප්‍රකාශ අතුරෙන් නිවැරදි වන්නේ කුමක්ද?</p>', NULL, 'ආලෝකයේ ෆෝටෝන මගින් ප්‍රභාපද්ධති I සහ II යන දෙකෙහිම වර්ණක අණු වල ඉලෙක්ට්‍රෝන උද්දීපනය කිරීම සිදු කරයි. ජලය බිඳ හෙලීමෙන් ප්‍රභාපද්ධති II හි ඉලෙක්ට්‍රෝන හිඩැස් පිරවෙන අතර, $NADP^{+}$ ඔක්සිහරණය කරන්නේ ප්‍රභාපද්ධති I මගිනි.', 'ආලෝකයේ ෆෝටෝන මගින් ප්‍රභාපද්ධති I සහ II යන දෙකෙහිම වර්ණක අණු වල ඉලෙක්ට්‍රෝන උද්දීපනය කිරීම සිදු කරයි. ජලය බිඳ හෙලීමෙන් ප්‍රභාපද්ධති II හි ඉලෙක්ට්‍රෝන හිඩැස් පිරවෙන අතර, $NADP^{+}$ ඔක්සිහරණය කරන්නේ ප්‍රභාපද්ධති I මගිනි.', NULL, 'sanitized', 'v1', 5, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('4934e003-d5be-4858-b8be-150c5d9d53cc', 'c9622b98-fcdd-5c3c-aa9c-9018daa27458', 'ආලෝකයේ ෆෝටෝන වර්ණක මත ගැටීම නිසා ප්‍රභාපද්ධති I හි සහ ප්‍රභාපද්ධති II හි ඉලෙක්ට්‍රෝන උද්දීපනය වේ.', 'ආලෝකයේ ෆෝටෝන වර්ණක මත ගැටීම නිසා ප්‍රභාපද්ධති I හි සහ ප්‍රභාපද්ධති II හි ඉලෙක්ට්‍රෝන උද්දීපනය වේ.', NULL, 'sanitized', 'v1', 0, 1);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('7d6c506c-4fda-4e9a-b484-3fa2bf2dc9a6', 'c9622b98-fcdd-5c3c-aa9c-9018daa27458', 'ප්‍රභාපද්ධති I හි අධි ශක්ති මට්ටමක ඇති ඉලෙක්ට්‍රෝන ප්‍රභාපද්ධති II හි ඇති ප්‍රාථමික ඉලෙක්ට්‍රෝන ප්‍රතිග්‍රාහකයක් මගින් ප්‍රතිග්‍රහණය කරනු ලැබේ.', 'ප්‍රභාපද්ධති I හි අධි ශක්ති මට්ටමක ඇති ඉලෙක්ට්‍රෝන ප්‍රභාපද්ධති II හි ඇති ප්‍රාථමික ඉලෙක්ට්‍රෝන ප්‍රතිග්‍රාහකයක් මගින් ප්‍රතිග්‍රහණය කරනු ලැබේ.', NULL, 'sanitized', 'v1', 1, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('4c22756f-7796-4597-b309-6ad70a36c0db', 'c9622b98-fcdd-5c3c-aa9c-9018daa27458', 'ප්‍රභාපද්ධති II හි ඇති උද්දීපනය වූ ඉලෙක්ට්‍රෝන $NADP^{+}$ ඔක්සිහරණය කරයි.', 'ප්‍රභාපද්ධති II හි ඇති උද්දීපනය වූ ඉලෙක්ට්‍රෝන $NADP^{+}$ ඔක්සිහරණය කරයි.', NULL, 'sanitized', 'v1', 2, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('821b8309-d576-4f60-8eec-fd833006a2d5', 'c9622b98-fcdd-5c3c-aa9c-9018daa27458', 'ජලය බිඳහෙලීම නිසා නිදහස් වන ඉලෙක්ට්‍රෝන උද්දීපනය වූ ප්‍රභා පද්ධති I උදාසීන කරයි.', 'ජලය බිඳහෙලීම නිසා නිදහස් වන ඉලෙක්ට්‍රෝන උද්දීපනය වූ ප්‍රභා පද්ධති I උදාසීන කරයි.', NULL, 'sanitized', 'v1', 3, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('9db0d713-35da-4252-ad46-2e7ff4304456', 'c9622b98-fcdd-5c3c-aa9c-9018daa27458', 'ක්ලෝරොෆිල් a අණුවක් සහ ක්ලෝරොෆිල් b අණුවක් සහිත සංවිධානය වූ ප්‍රෝටීන ප්‍රතික්‍රියා මධ්‍යස්ථාන සංකීර්ණයේ ඇත.', 'ක්ලෝරොෆිල් a අණුවක් සහ ක්ලෝරොෆිල් b අණුවක් සහිත සංවිධානය වූ ප්‍රෝටීන ප්‍රතික්‍රියා මධ්‍යස්ථාන සංකීර්ණයේ ඇත.', NULL, 'sanitized', 'v1', 4, 0);
INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('3cceeb82-af22-5572-ac59-627e75144a8a', '29f5bbf4-11d0-52b2-9c36-80bd6211f940', 9, '<p>ජීවීන් වර්ගීකරණය කිරීමේදී වයිරස කිසිම රාජධානියකට ඇතුළත් කර නොමැත්තේ ඒවා</p>', '<p>ජීවීන් වර්ගීකරණය කිරීමේදී වයිරස කිසිම රාජධානියකට ඇතුළත් කර නොමැත්තේ ඒවා</p>', NULL, 'ජීවය පිළිබඳ මූලිකම ව්‍යුහාත්මක ඒකකය සෛලයයි. වයිරස වලට සෛලීය සංවිධානයක් (Cellular organization) නොමැති නිසා ඒවා සම්භාව්‍ය ජීවී රාජධානි වර්ගීකරණයට ඇතුළත් නොකෙරේ.', 'ජීවය පිළිබඳ මූලිකම ව්‍යුහාත්මක ඒකකය සෛලයයි. වයිරස වලට සෛලීය සංවිධානයක් (Cellular organization) නොමැති නිසා ඒවා සම්භාව්‍ය ජීවී රාජධානි වර්ගීකරණයට ඇතුළත් නොකෙරේ.', NULL, 'sanitized', 'v1', 5, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
