INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('7ed9714b-a24c-4977-ae3c-8885ba743e2a', '3cceeb82-af22-5572-ac59-627e75144a8a', 'ප්‍රෝටීන සංශ්ලේෂණ යන්ත්‍රණයක් නොදරන බැවිනි.', 'ප්‍රෝටීන සංශ්ලේෂණ යන්ත්‍රණයක් නොදරන බැවිනි.', NULL, 'sanitized', 'v1', 1, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('b799b9fe-6270-4460-858b-f7692260f6c2', '3cceeb82-af22-5572-ac59-627e75144a8a', 'ධාරක සෛල තුළදී පමණක් පරිවෘත්තීය ක්‍රියා දක්වන බැවිනි.', 'ධාරක සෛල තුළදී පමණක් පරිවෘත්තීය ක්‍රියා දක්වන බැවිනි.', NULL, 'sanitized', 'v1', 2, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('30ddc5f0-03e8-4b32-9cc2-1e7ea441ffc1', '3cceeb82-af22-5572-ac59-627e75144a8a', 'ප්‍රවේණික ද්‍රව්‍ය ලෙස RNA දරන බැවිනි.', 'ප්‍රවේණික ද්‍රව්‍ය ලෙස RNA දරන බැවිනි.', NULL, 'sanitized', 'v1', 3, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('991eb911-6d96-4a8b-aeee-5f0941c0ed03', '3cceeb82-af22-5572-ac59-627e75144a8a', 'සෛලීය සංවිධානයක් නොදක්වන බැවිනි.', 'සෛලීය සංවිධානයක් නොදක්වන බැවිනි.', NULL, 'sanitized', 'v1', 4, 0);
INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('10dc7a9f-ef15-566d-b29a-c31acc154901', '29f5bbf4-11d0-52b2-9c36-80bd6211f940', 10, '<p>ද්විලිංගික ජන්මාණු ශාකයක් සහ ප්‍රමුඛ බීජාණු ශාකයක් සහිත සමබීජාණුක භෞමික ශාකයක් අයත් වන වංශය බොහෝ විට</p>', '<p>ද්විලිංගික ජන්මාණු ශාකයක් සහ ප්‍රමුඛ බීජාණු ශාකයක් සහිත සමබීජාණුක භෞමික ශාකයක් අයත් වන වංශය බොහෝ විට</p>', NULL, 'ටෙරොෆයිටා (Pterophyta - උදා: මීවන) වංශයේ ශාක වල ප්‍රමුඛ පරම්පරාව බීජාණු ශාකය වේ. ඒවා සමබීජාණුක වන බැවින් එහි ජන්මාණු ශාකය (ප්‍රෝතලසය) ද්විලිංගික (bisexual) වේ.', 'ටෙරොෆයිටා (Pterophyta - උදා: මීවන) වංශයේ ශාක වල ප්‍රමුඛ පරම්පරාව බීජාණු ශාකය වේ. ඒවා සමබීජාණුක වන බැවින් එහි ජන්මාණු ශාකය (ප්‍රෝතලසය) ද්විලිංගික (bisexual) වේ.', NULL, 'sanitized', 'v1', 5, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
