INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('b19e14f5-f4e6-46f6-8e34-8caa37e4d3d5', '10dc7a9f-ef15-566d-b29a-c31acc154901', 'නීටොෆයිටා විය හැකි ය.', 'නීටොෆයිටා විය හැකි ය.', NULL, 'sanitized', 'v1', 3, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('8cc763ce-ebd4-4359-805d-8e42bbee27f0', '10dc7a9f-ef15-566d-b29a-c31acc154901', 'කොනිෆෙරොෆයිටා විය හැකි ය.', 'කොනිෆෙරොෆයිටා විය හැකි ය.', NULL, 'sanitized', 'v1', 4, 0);
INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('adc054a7-6935-546e-9803-c3ea9948db38', '29f5bbf4-11d0-52b2-9c36-80bd6211f940', 11, '<p>ඒක ලිංගික සතුන් සිටිනුයේ පහත සඳහන් කුමන වංශයේ ද? / වංශවලද?<br><br>A - නෙමටෝඩා<br>B - ආත්‍රොපෝඩා<br>C - ප්ලැටිහෙල්මින්තස්<br>D - එකයිනොඩමේටා</p>', '<p>ඒක ලිංගික සතුන් සිටිනුයේ පහත සඳහන් කුමන වංශයේ ද? / වංශවලද?<br><br>A - නෙමටෝඩා<br>B - ආත්‍රොපෝඩා<br>C - ප්ලැටිහෙල්මින්තස්<br>D - එකයිනොඩමේටා</p>', NULL, 'නෙමටෝඩා (Nematoda - වටපණුවන්), ආත්‍රොපෝඩා (Arthropoda - සන්ධිපාදකයින්) සහ එකයිනොඩමේටා (Echinodermata) යන වංශ වලට අයත් බහුතරයක් සතුන් ඒකලිංගික (dioecious) වේ. නමුත් ප්ලැටිහෙල්මින්තස් (Platyhelminthes - පැතලි පණුවන්) වංශයේ බොහෝ සතුන් ද්විලිංගික (monoecious) වේ.', 'නෙමටෝඩා (Nematoda - වටපණුවන්), ආත්‍රොපෝඩා (Arthropoda - සන්ධිපාදකයින්) සහ එකයිනොඩමේටා (Echinodermata) යන වංශ වලට අයත් බහුතරයක් සතුන් ඒකලිංගික (dioecious) වේ. නමුත් ප්ලැටිහෙල්මින්තස් (Platyhelminthes - පැතලි පණුවන්) වංශයේ බොහෝ සතුන් ද්විලිංගික (monoecious) වේ.', NULL, 'sanitized', 'v1', 5, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
