INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('4e27e787-35e7-4478-82d3-7c565385c494', '0ac8c11e-e9ba-5322-b975-ae361af0d6d0', 'හෘත් ස්ඵන්දනයේ රිද්මය ඇති කරනු ලබන්නේ AV ගැටය මගිනි.', 'හෘත් ස්ඵන්දනයේ රිද්මය ඇති කරනු ලබන්නේ AV ගැටය මගිනි.', NULL, 'sanitized', 'v1', 3, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('f76e8637-8094-4c2b-bc75-dbb4a72bbd09', '0ac8c11e-e9ba-5322-b975-ae361af0d6d0', 'AV ගැටයේ විද්‍යුත් ආවේග, හෘදයේ අග්‍රය දෙසට සංකෝචක තරංග පැතිරීම ක්‍රියාරම්හ කරයි.', 'AV ගැටයේ විද්‍යුත් ආවේග, හෘදයේ අග්‍රය දෙසට සංකෝචක තරංග පැතිරීම ක්‍රියාරම්හ කරයි.', NULL, 'sanitized', 'v1', 4, 0);
INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('1bd3a671-fa63-554e-ac2c-760a60ef7d43', '29f5bbf4-11d0-52b2-9c36-80bd6211f940', 21, '<p>මානව පෙණහැලි පිළිබඳ පහත සඳහන් ප්‍රකාශ අතුරෙන් නිවැරදි වන්නේ කුමක්ද?</p>', '<p>මානව පෙණහැලි පිළිබඳ පහත සඳහන් ප්‍රකාශ අතුරෙන් නිවැරදි වන්නේ කුමක්ද?</p>', NULL, 'වම් පෙනහල්ලේ හෘදය පිහිටීම සඳහා වූ හෘත් කඩතොල්ලක් (cardiac notch) පවතින බැවින්, එය දකුණු පෙනහල්ලට වඩා ස්වල්පයක් කුඩා වේ. දකුණු පෙනහල්ල ඛණ්ඩිකා 3කින් සමන්විත අතර වම් පෙනහල්ල ඛණ්ඩිකා 2කින් සමන්විතය.', 'වම් පෙනහල්ලේ හෘදය පිහිටීම සඳහා වූ හෘත් කඩතොල්ලක් (cardiac notch) පවතින බැවින්, එය දකුණු පෙනහල්ලට වඩා ස්වල්පයක් කුඩා වේ. දකුණු පෙනහල්ල ඛණ්ඩිකා 3කින් සමන්විත අතර වම් පෙනහල්ල ඛණ්ඩිකා 2කින් සමන්විතය.', NULL, 'sanitized', 'v1', 5, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('f2ddebdd-1541-4ac5-bd53-d4bc732d2415', '1bd3a671-fa63-554e-ac2c-760a60ef7d43', 'එක් එක් පෙණහැල්ල බාහිර අන්තරංග ප්ලූරාවෙන් සහ අභ්‍යන්තර පාර්ශ්වික ප්ලූරාවෙන් වට වී ඇත.', 'එක් එක් පෙණහැල්ල බාහිර අන්තරංග ප්ලූරාවෙන් සහ අභ්‍යන්තර පාර්ශ්වික ප්ලූරාවෙන් වට වී ඇත.', NULL, 'sanitized', 'v1', 0, 1);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('d07b2d03-6c58-4658-8be8-cfd4b06fe093', '1bd3a671-fa63-554e-ac2c-760a60ef7d43', 'වම් පෙනහැල්ල, දකුණු පෙණහැල්ලට වඩා ස්වල්පයක් කුඩාය.', 'වම් පෙනහැල්ල, දකුණු පෙණහැල්ලට වඩා ස්වල්පයක් කුඩාය.', NULL, 'sanitized', 'v1', 1, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('1c13e716-df30-4d89-9e0b-367e70d652cf', '1bd3a671-fa63-554e-ac2c-760a60ef7d43', 'දකුණු පෙණහැල්ල ඛණ්ඩිකා දෙකකින් සමන්විත වේ.', 'දකුණු පෙණහැල්ල ඛණ්ඩිකා දෙකකින් සමන්විත වේ.', NULL, 'sanitized', 'v1', 2, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('82f0cbea-992b-440b-96b4-49dee2c577f8', '1bd3a671-fa63-554e-ac2c-760a60ef7d43', 'ගර්ත තුළ ඇති ශ්ලේෂ්මලය මගින් ආශ්වාස වාතයේ ඇති දූවිලි අංශු රඳවා ගැනේ.', 'ගර්ත තුළ ඇති ශ්ලේෂ්මලය මගින් ආශ්වාස වාතයේ ඇති දූවිලි අංශු රඳවා ගැනේ.', NULL, 'sanitized', 'v1', 3, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('74764fca-cc9c-4790-960c-d23011b6216e', '1bd3a671-fa63-554e-ac2c-760a60ef7d43', 'ගර්තවල අපිච්ඡදයේ ඇති පක්ෂ්ම පෘෂ්ඨාතති ශමකයේ චලනයට උපකාරී වේ.', 'ගර්තවල අපිච්ඡදයේ ඇති පක්ෂ්ම පෘෂ්ඨාතති ශමකයේ චලනයට උපකාරී වේ.', NULL, 'sanitized', 'v1', 4, 0);
INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('89d5b759-84f4-5b71-b213-67b4da253226', '29f5bbf4-11d0-52b2-9c36-80bd6211f940', 22, '<p>මානව වෘක්කාණුවේ ව්‍යුහමය කොටස් කිහිපයක් සහ මූත්‍ර සෑදීමේදී සිදුවන ක්‍රියාවලි කිහිපයක් පහත දී ඇත.<br><br>ව්‍යුහමය කොටස<br>A - අවිදුර සංවලිත නාලිකාව<br>B - හෙන්ලේ පුඩුවේ අවරෝහණ බාහුව<br>C - හෙන්ලේ පුඩුවේ ආරෝහණ බාහුව<br>D - විදුර සංවලිත නාලිකාව<br><br>ක්‍රියාවලිය<br>P - $K^{+}$ ස්‍රාවය කිරීම<br>Q - $HCO_{3}^{-}$ ප්‍රතිශෝෂණය<br>R - ජලය ප්‍රතිශෝෂණය<br><br>සියලු ම '' ව්‍යුහමය කොටස - ක්‍රියාවලිය'' සංකලන නිවැරදි වන වරණය තෝරන්න.</p>', '<p>මානව වෘක්කාණුවේ ව්‍යුහමය කොටස් කිහිපයක් සහ මූත්‍ර සෑදීමේදී සිදුවන ක්‍රියාවලි කිහිපයක් පහත දී ඇත.<br><br>ව්‍යුහමය කොටස<br>A - අවිදුර සංවලිත නාලිකාව<br>B - හෙන්ලේ පුඩුවේ අවරෝහණ බාහුව<br>C - හෙන්ලේ පුඩුවේ ආරෝහණ බාහුව<br>D - විදුර සංවලිත නාලිකාව<br><br>ක්‍රියාවලිය<br>P - $K^{+}$ ස්‍රාවය කිරීම<br>Q - $HCO_{3}^{-}$ ප්‍රතිශෝෂණය<br>R - ජලය ප්‍රතිශෝෂණය<br><br>සියලු ම '' ව්‍යුහමය කොටස - ක්‍රියාවලිය'' සංකලන නිවැරදි වන වරණය තෝරන්න.</p>', NULL, 'අවිදුර සංවලිත නාලිකාවේදී (A) රුධිරයේ pH අගය පවත්වා ගැනීම සඳහා $HCO_3^-$ ප්‍රතිශෝෂණය (Q) සිදුවේ. හෙන්ලේ පුඩුවේ අවරෝහණ බාහුව (B) ජලයට පාරගම්‍ය බැවින් ජලය ප්‍රතිශෝෂණය (R) සිදුවේ. විදුර සංවලිත නාලිකාවේදී (D) රුධිරයේ සිට නාලිකාවට $K^+$ ස්‍රාවය කිරීම (P) සිදුවේ.', 'අවිදුර සංවලිත නාලිකාවේදී (A) රුධිරයේ pH අගය පවත්වා ගැනීම සඳහා $HCO_3^-$ ප්‍රතිශෝෂණය (Q) සිදුවේ. හෙන්ලේ පුඩුවේ අවරෝහණ බාහුව (B) ජලයට පාරගම්‍ය බැවින් ජලය ප්‍රතිශෝෂණය (R) සිදුවේ. විදුර සංවලිත නාලිකාවේදී (D) රුධිරයේ සිට නාලිකාවට $K^+$ ස්‍රාවය කිරීම (P) සිදුවේ.', NULL, 'sanitized', 'v1', 5, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
