INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('65b3a54c-4411-4574-9266-5d03ea91fe83', 'cd7bffe9-bb85-5068-9815-99215e63fd8e', 'ලිංගේන්ද්‍රියන් උද්ගමනය වීම දිරි ගන්වයි.', 'ලිංගේන්ද්‍රියන් උද්ගමනය වීම දිරි ගන්වයි.', NULL, 'sanitized', 'v1', 1, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('162b55d4-ec5d-4613-98c9-c3d57c6dab48', 'cd7bffe9-bb85-5068-9815-99215e63fd8e', 'මුත්‍රාශය හිස්වීම දිරි ගන්වයි.', 'මුත්‍රාශය හිස්වීම දිරි ගන්වයි.', NULL, 'sanitized', 'v1', 2, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('02e97ca8-8179-4fa5-92d6-68ba5ceca1e6', 'cd7bffe9-bb85-5068-9815-99215e63fd8e', 'අධිවෘක්ක මජ්ජාව උත්තේජනය කරයි.', 'අධිවෘක්ක මජ්ජාව උත්තේජනය කරයි.', NULL, 'sanitized', 'v1', 3, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('eeffe176-a00a-494f-8911-7ea5c892cbc2', 'cd7bffe9-bb85-5068-9815-99215e63fd8e', 'පෙණහැලි තුළ ඇති ශ්වාසනාලිකා සංකුචනය කරයි.', 'පෙණහැලි තුළ ඇති ශ්වාසනාලිකා සංකුචනය කරයි.', NULL, 'sanitized', 'v1', 4, 0);
INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('ac46d567-e629-5c24-93b1-3aa55e73c3fe', '29f5bbf4-11d0-52b2-9c36-80bd6211f940', 24, '<p>අන්තෝ වසා තරලයෙන් පිරී ඇත්තේ මානව කනේ පහත සඳහන් කුමන ව්‍යුහද?</p>', '<p>අන්තෝ වසා තරලයෙන් පිරී ඇත්තේ මානව කනේ පහත සඳහන් කුමන ව්‍යුහද?</p>', NULL, 'අභ්‍යන්තර කනේ ඇති පටලමය ගහනය (membranous labyrinth) අන්තෝවසාවෙන් (endolymph) පිරී පවතී. කර්ණ ශංඛ ප්‍රණාලය (cochlear duct), තුම්බිකාව (utricle), මඩිච්චිය (saccule) සහ අර්ධ චක්‍රාකාර නාල මෙම පටලමය ගහනයට අයත් වේ. අලින්ද නාලය සහ කර්ණ පටහ නාලය පිරී ඇත්තේ පරිවසාවෙනි (perilymph).', 'අභ්‍යන්තර කනේ ඇති පටලමය ගහනය (membranous labyrinth) අන්තෝවසාවෙන් (endolymph) පිරී පවතී. කර්ණ ශංඛ ප්‍රණාලය (cochlear duct), තුම්බිකාව (utricle), මඩිච්චිය (saccule) සහ අර්ධ චක්‍රාකාර නාල මෙම පටලමය ගහනයට අයත් වේ. අලින්ද නාලය සහ කර්ණ පටහ නාලය පිරී ඇත්තේ පරිවසාවෙනි (perilymph).', NULL, 'sanitized', 'v1', 5, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('10a75bb1-8710-421d-8bc0-9a768a9f9136', 'ac46d567-e629-5c24-93b1-3aa55e73c3fe', 'අලින්ද නාලය. කර්ණ පටහ නාලය සහ කර්ණශංඛ ප්‍රණාලය', 'අලින්ද නාලය. කර්ණ පටහ නාලය සහ කර්ණශංඛ ප්‍රණාලය', NULL, 'sanitized', 'v1', 0, 1);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('7d14ff53-ab82-44a5-83f1-ecbb93a1a11d', 'ac46d567-e629-5c24-93b1-3aa55e73c3fe', 'කර්ණශංඛ ප්‍රණාලය, අලින්ද නාලය සහ තුම්බිකාව', 'කර්ණශංඛ ප්‍රණාලය, අලින්ද නාලය සහ තුම්බිකාව', NULL, 'sanitized', 'v1', 1, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('30ebbeea-79c3-4232-a08f-cdf7efbbd5c4', 'ac46d567-e629-5c24-93b1-3aa55e73c3fe', 'කර්ණපටහ නාලය, කර්ණ ශංඛ ප්‍රණාලය සහ මඩිච්චිය', 'කර්ණපටහ නාලය, කර්ණ ශංඛ ප්‍රණාලය සහ මඩිච්චිය', NULL, 'sanitized', 'v1', 2, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('a3f457ab-298d-4908-8919-6e0c4c3e44f8', 'ac46d567-e629-5c24-93b1-3aa55e73c3fe', 'තුම්බිකාව, මඩිව්ච්චිය සහ අලින්ද නාලය', 'තුම්බිකාව, මඩිව්ච්චිය සහ අලින්ද නාලය', NULL, 'sanitized', 'v1', 3, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('d000a844-5e1c-40c3-82ee-cb66b79dc3c5', 'ac46d567-e629-5c24-93b1-3aa55e73c3fe', 'කර්ණශංඛ ප්‍රණාලය, තුම්බිකාව සහ මඩිච්චිය', 'කර්ණශංඛ ප්‍රණාලය, තුම්බිකාව සහ මඩිච්චිය', NULL, 'sanitized', 'v1', 4, 0);
INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('5ce0d066-6dfa-53fa-a902-1fdea556ea6b', '29f5bbf4-11d0-52b2-9c36-80bd6211f940', 25, '<p>මානව රුධිරයේ ආස්‍රැති මෞලිකතාව කායික විද්‍යාත්මක සීමා ඉක්මවා වැඩි වූ විට සමස්ථිතිය ඇති කිරීම සඳහා සිදු වන්නේ පහත සඳහන් කුමන සිදුවීම් ශ්‍රේණිය ද?<br><br>ADH නිදහස් වීම | ජලය සඳහා වෘක්ක නාලිකාවල පාරගම්‍යතාව | නිපදවෙන මූත්‍ර ප්‍රමාණය</p>', '<p>මානව රුධිරයේ ආස්‍රැති මෞලිකතාව කායික විද්‍යාත්මක සීමා ඉක්මවා වැඩි වූ විට සමස්ථිතිය ඇති කිරීම සඳහා සිදු වන්නේ පහත සඳහන් කුමන සිදුවීම් ශ්‍රේණිය ද?<br><br>ADH නිදහස් වීම | ජලය සඳහා වෘක්ක නාලිකාවල පාරගම්‍යතාව | නිපදවෙන මූත්‍ර ප්‍රමාණය</p>', NULL, 'රුධිරයේ ආස්‍රැති මෞලිකතාව (osmolarity) වැඩි වූ විට (රුධිරයේ ජල විභවය අඩු වූ විට), හයිපොතැලමස මගින් සංවේදනය කර පසුපිටියුටරිය හරහා ADH හෝමෝනය නිදහස් කිරීම *වැඩි* කරයි. එමගින් වෘක්ක නාලිකාවල ජලය සඳහා පාරගම්‍යතාව *වැඩි* කරන අතර, ජලය ප්‍රතිශෝෂණය වීම නිසා නිපදවෙන මූත්‍ර ප්‍රමාණය *අඩු* වේ.', 'රුධිරයේ ආස්‍රැති මෞලිකතාව (osmolarity) වැඩි වූ විට (රුධිරයේ ජල විභවය අඩු වූ විට), හයිපොතැලමස මගින් සංවේදනය කර පසුපිටියුටරිය හරහා ADH හෝමෝනය නිදහස් කිරීම *වැඩි* කරයි. එමගින් වෘක්ක නාලිකාවල ජලය සඳහා පාරගම්‍යතාව *වැඩි* කරන අතර, ජලය ප්‍රතිශෝෂණය වීම නිසා නිපදවෙන මූත්‍ර ප්‍රමාණය *අඩු* වේ.', NULL, 'sanitized', 'v1', 5, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
