INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('8b6e1087-c8f6-4e80-a291-1d504fe049fd', '830010ca-dfdf-5db2-a009-e9f4a432b841', 'කටී කශේරුකාවක එක් එක් තීරයක් ප්‍රසරයේ කශේරුක ධමනියට ගමන් කිරීම සඳහා ඡිද්‍රයක් බැගින් ඇත.', 'කටී කශේරුකාවක එක් එක් තීරයක් ප්‍රසරයේ කශේරුක ධමනියට ගමන් කිරීම සඳහා ඡිද්‍රයක් බැගින් ඇත.', NULL, 'sanitized', 'v1', 2, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('e3efec00-32c1-45e8-af8f-f6aa8f8a2ffc', '830010ca-dfdf-5db2-a009-e9f4a432b841', 'එහි උරස් වක්‍රය පුර්ව දෙසට උත්තල ය.', 'එහි උරස් වක්‍රය පුර්ව දෙසට උත්තල ය.', NULL, 'sanitized', 'v1', 3, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('a85051bb-ace0-472d-b534-17430ca2f80b', '830010ca-dfdf-5db2-a009-e9f4a432b841', 'ස්නායුවලට ගමන් කිරීම සඳහා ත්‍රිකාස්ථියේ එක් එක් පැත්තේ ඡිද්‍ර ශ්‍රේණියක් බැගින් ඇත.', 'ස්නායුවලට ගමන් කිරීම සඳහා ත්‍රිකාස්ථියේ එක් එක් පැත්තේ ඡිද්‍ර ශ්‍රේණියක් බැගින් ඇත.', NULL, 'sanitized', 'v1', 4, 0);
INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('f83fc8e8-02c0-5064-99ad-e3efef007f41', '29f5bbf4-11d0-52b2-9c36-80bd6211f940', 29, '<p>මානව ගාත්‍රා සැකිල්ලේ</p>', '<p>මානව ගාත්‍රා සැකිල්ලේ</p>', NULL, 'මානව උකුළු සන්ධිය (Hip joint) ද්විපාදිකත්වයට (bipedalism) අනුගත වෙමින්, සිටගෙන සිටීමේදී දේහයේ බර ඵලදායී ලෙස දරා ගැනීම සඳහා ඉතා දැඩි හා ශක්තිමත් වී ඇත. ප්‍රගන්ඩාස්ථියේ හිස සන්ධානය වන්නේ අංසඵලකය (scapula) සමගය. දණහිස් සන්ධිය අසව් සන්ධියක් (hinge joint) වන බැවින් එයින් ප්‍රධාන වශයෙන් සිදු කළ හැක්කේ නැමීම සහ දිගහැරීමයි.', 'මානව උකුළු සන්ධිය (Hip joint) ද්විපාදිකත්වයට (bipedalism) අනුගත වෙමින්, සිටගෙන සිටීමේදී දේහයේ බර ඵලදායී ලෙස දරා ගැනීම සඳහා ඉතා දැඩි හා ශක්තිමත් වී ඇත. ප්‍රගන්ඩාස්ථියේ හිස සන්ධානය වන්නේ අංසඵලකය (scapula) සමගය. දණහිස් සන්ධිය අසව් සන්ධියක් (hinge joint) වන බැවින් එයින් ප්‍රධාන වශයෙන් සිදු කළ හැක්කේ නැමීම සහ දිගහැරීමයි.', NULL, 'sanitized', 'v1', 5, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('f71faade-1155-44d1-89f7-bbd8f3dbe7cc', 'f83fc8e8-02c0-5064-99ad-e3efef007f41', 'ප්‍රගන්ඩාස්ථියේ හිස අක්ෂකාස්ථිය සමග පුළුල් පරාසයක චලනය සඳහා ඉඩ සලසන ගෝල කුහර සන්ධියක් තනයි.', 'ප්‍රගන්ඩාස්ථියේ හිස අක්ෂකාස්ථිය සමග පුළුල් පරාසයක චලනය සඳහා ඉඩ සලසන ගෝල කුහර සන්ධියක් තනයි.', NULL, 'sanitized', 'v1', 0, 1);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('134371bc-fa5c-42ee-bf5e-31bcde5d3a14', 'f83fc8e8-02c0-5064-99ad-e3efef007f41', 'ප්‍රගන්ඩාස්ථියේ විදුර කෙළවර ඇති තනි සන්ධාන පෘෂ්ඨය සමග අරාස්ථිය සහ අන්වරාස්ථිය සන්ධානය වීමෙන් වැලමිට සන්ධිය තැනේ.', 'ප්‍රගන්ඩාස්ථියේ විදුර කෙළවර ඇති තනි සන්ධාන පෘෂ්ඨය සමග අරාස්ථිය සහ අන්වරාස්ථිය සන්ධානය වීමෙන් වැලමිට සන්ධිය තැනේ.', NULL, 'sanitized', 'v1', 1, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('0fff8d6f-2c5c-4901-aaca-0c50554d4f94', 'f83fc8e8-02c0-5064-99ad-e3efef007f41', 'පළමුවැනි හස්තකූර්චෝපරී අස්ථිය සහ හස්තකුර්වාස්ථියක් අතර මහපටැඟිල්ලේ පාදස්ථයේ තැනෙන සන්ධිය නිසා බල ග්‍රහණ හැකියාව ලැබී ඇත.', 'පළමුවැනි හස්තකූර්චෝපරී අස්ථිය සහ හස්තකුර්වාස්ථියක් අතර මහපටැඟිල්ලේ පාදස්ථයේ තැනෙන සන්ධිය නිසා බල ග්‍රහණ හැකියාව ලැබී ඇත.', NULL, 'sanitized', 'v1', 2, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('89400ded-1c1f-449f-934f-8d5564043625', 'f83fc8e8-02c0-5064-99ad-e3efef007f41', 'සිටගෙන සිටින විට දේහ බර දරාගැනීම සඳහා උකුළු සන්ධිය ඉතා දැඩි සහ ශක්තිමත් වී ඇත.', 'සිටගෙන සිටින විට දේහ බර දරාගැනීම සඳහා උකුළු සන්ධිය ඉතා දැඩි සහ ශක්තිමත් වී ඇත.', NULL, 'sanitized', 'v1', 3, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('58337d2a-a9d3-4898-b31b-0133076490e0', 'f83fc8e8-02c0-5064-99ad-e3efef007f41', 'ඌර්වස්ථිය සහ ජංඝාස්ථිය මගින් තැනෙන දණහිස් සන්ධිය භ්‍රමණ චලනයට ඉඩ සලසයි.', 'ඌර්වස්ථිය සහ ජංඝාස්ථිය මගින් තැනෙන දණහිස් සන්ධිය භ්‍රමණ චලනයට ඉඩ සලසයි.', NULL, 'sanitized', 'v1', 4, 0);
INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('027ce685-3cde-50e4-a521-446d46d3002f', '29f5bbf4-11d0-52b2-9c36-80bd6211f940', 30, '<p>හාඩි - වයින්බර්ග් සමතුලිතතාවේ ඇති ගෙවතු මෑ ශාක ගහනයක පුෂ්පවල රතු වර්ණය සඳහා වන ඇලීලය, සුදු වර්ණය සඳහා වන ඇලීලයට ප්‍රමුඛ වේ.<br><br>මෙම ගහනයේ නිලීන ඇලීල සංඛ්‍යාතය 0.3 නම් විෂමයුග්මක ශාකවල ප්‍රවේණිදර්ශ සංඛ්‍යාතය කුමක්ද?</p>', '<p>හාඩි - වයින්බර්ග් සමතුලිතතාවේ ඇති ගෙවතු මෑ ශාක ගහනයක පුෂ්පවල රතු වර්ණය සඳහා වන ඇලීලය, සුදු වර්ණය සඳහා වන ඇලීලයට ප්‍රමුඛ වේ.<br><br>මෙම ගහනයේ නිලීන ඇලීල සංඛ්‍යාතය 0.3 නම් විෂමයුග්මක ශාකවල ප්‍රවේණිදර්ශ සංඛ්‍යාතය කුමක්ද?</p>', NULL, 'නිලීන ඇලීල සංඛ්‍යාතය ($q$) = 0.3<br>එබැවින් ප්‍රමුඛ ඇලීල සංඛ්‍යාතය ($p$) = $1 - 0.3 = 0.7$<br>හාඩි-වයින්බර්ග් සමීකරණයට අනුව, විෂම යුග්මක (heterozygous) ශාකවල ප්‍රවේණි දර්ශ සංඛ්‍යාතය = $2pq$<br>$2pq = 2 \times 0.7 \times 0.3 = 0.42$', 'නිලීන ඇලීල සංඛ්‍යාතය ($q$) = 0.3<br>එබැවින් ප්‍රමුඛ ඇලීල සංඛ්‍යාතය ($p$) = $1 - 0.3 = 0.7$<br>හාඩි-වයින්බර්ග් සමීකරණයට අනුව, විෂම යුග්මක (heterozygous) ශාකවල ප්‍රවේණි දර්ශ සංඛ්‍යාතය = $2pq$<br>$2pq = 2 \times 0.7 \times 0.3 = 0.42$', NULL, 'sanitized', 'v1', 5, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
