INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('05bb3ae8-f1ef-4dbf-aac3-661484b2028d', 'ff71aea3-c0d8-5782-8adf-d5390d82f320', 'බඩඉරිඟු → මීයා → සර්පයා → බකමුණා', 'බඩඉරිඟු → මීයා → සර්පයා → බකමුණා', NULL, 'sanitized', 'v1', 2, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('9664630f-317e-4d23-a5a1-5c8626df0e43', 'ff71aea3-c0d8-5782-8adf-d5390d82f320', 'තෘණ → සීබ්‍රා → සයිබීරියානු කොටියා', 'තෘණ → සීබ්‍රා → සයිබීරියානු කොටියා', NULL, 'sanitized', 'v1', 3, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('866acf5c-b6b0-43fd-9fca-5c800fbc03e9', 'ff71aea3-c0d8-5782-8adf-d5390d82f320', 'තෘණ → තණකොල පෙත්තා → ගෙම්බා → සර්පයා → රාජාලියා', 'තෘණ → තණකොල පෙත්තා → ගෙම්බා → සර්පයා → රාජාලියා', NULL, 'sanitized', 'v1', 4, 0);
INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('93889065-22fa-5cef-8ab5-95ecf35cda39', '29f5bbf4-11d0-52b2-9c36-80bd6211f940', 35, '<p>බියෝම කිහිපයක් සහ ඒවායේ සාමාන්‍යයෙන් දැකිය හැකි සතුන් කිහිප දෙනෙකු පහත දී ඇත.<br><br>බියෝමය<br>A - සැවානා<br>B - තුන්ද්‍රා<br>C - උතුරු කේතුධර වනාන්තර<br>D - චැපරාල්<br><br>සත්ත්වයා<br>P - පිණිමුවා<br>Q - එළුවා<br>R - සිංහයා<br>S - දුඹුරු වළහා<br><br>සියලුම '' බියෝමය - සත්ත්වයා'' සංකලන නිවැරදි වන වරණය තෝරන්න.</p>', '<p>බියෝම කිහිපයක් සහ ඒවායේ සාමාන්‍යයෙන් දැකිය හැකි සතුන් කිහිප දෙනෙකු පහත දී ඇත.<br><br>බියෝමය<br>A - සැවානා<br>B - තුන්ද්‍රා<br>C - උතුරු කේතුධර වනාන්තර<br>D - චැපරාල්<br><br>සත්ත්වයා<br>P - පිණිමුවා<br>Q - එළුවා<br>R - සිංහයා<br>S - දුඹුරු වළහා<br><br>සියලුම '' බියෝමය - සත්ත්වයා'' සංකලන නිවැරදි වන වරණය තෝරන්න.</p>', NULL, 'සැවානා (A) බියෝමයේ සිංහයා (R) දැකිය හැක. තුන්ද්‍රා (B) බියෝමයේ පිණිමුවා (Reindeer/Caribou - P) දැකිය හැක. උතුරු කේතුධර වනාන්තර (C) වල දුඹුරු වළහා (Brown bear - S) සහ චැපරාල් (D) වල එළුවා, මුවා වැනි සතුන් (Q) දැකිය හැක.', 'සැවානා (A) බියෝමයේ සිංහයා (R) දැකිය හැක. තුන්ද්‍රා (B) බියෝමයේ පිණිමුවා (Reindeer/Caribou - P) දැකිය හැක. උතුරු කේතුධර වනාන්තර (C) වල දුඹුරු වළහා (Brown bear - S) සහ චැපරාල් (D) වල එළුවා, මුවා වැනි සතුන් (Q) දැකිය හැක.', NULL, 'sanitized', 'v1', 5, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
