INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('b7ffeb9f-db1a-57aa-8ca8-14ad48a6b86d', '29f5bbf4-11d0-52b2-9c36-80bd6211f940', 39, '<p>කෝලිෆෝම් බැක්ටීරියා යනු</p>', '<p>කෝලිෆෝම් බැක්ටීරියා යනු</p>', NULL, 'ජල දූෂණය මැනීම සඳහා දර්ශක ජීවීන් ලෙස යොදා ගන්නා කෝලිෆෝම් (Coliforms) බැක්ටීරියා යනු ග්‍රෑම් ඍණ, යෂ්ටි හැඩැති, අන්තඃබීජාණු නොසාදන සහ $35^{\circ}C$ උෂ්ණත්වයකදී පැය 48 ක් ඇතුළත ලැක්ටෝස් පැසීමට ලක්කර අම්ල හා වායු නිපදවන බැක්ටීරියා කාණ්ඩයකි.', 'ජල දූෂණය මැනීම සඳහා දර්ශක ජීවීන් ලෙස යොදා ගන්නා කෝලිෆෝම් (Coliforms) බැක්ටීරියා යනු ග්‍රෑම් ඍණ, යෂ්ටි හැඩැති, අන්තඃබීජාණු නොසාදන සහ $35^{\circ}C$ උෂ්ණත්වයකදී පැය 48 ක් ඇතුළත ලැක්ටෝස් පැසීමට ලක්කර අම්ල හා වායු නිපදවන බැක්ටීරියා කාණ්ඩයකි.', NULL, 'sanitized', 'v1', 5, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('2e39123d-bd63-4ef1-9c8a-bca630bf095b', 'b7ffeb9f-db1a-57aa-8ca8-14ad48a6b86d', 'යෂ්ටි හැඩැති, ග්‍රෑම් ඍණ, අන්තඃ බීජාණු නොසාදන, ලැක්ටෝස් ද්‍රව රෝපණ මාධ්‍යය $60^{\circ}C$ දී පැසීමෙන් පැය 24 ක් ඇතුළත වායු වර්ග නිපදවන බැක්ටීරියා වේ.', 'යෂ්ටි හැඩැති, ග්‍රෑම් ඍණ, අන්තඃ බීජාණු නොසාදන, ලැක්ටෝස් ද්‍රව රෝපණ මාධ්‍යය $60^{\circ}C$ දී පැසීමෙන් පැය 24 ක් ඇතුළත වායු වර්ග නිපදවන බැක්ටීරියා වේ.', NULL, 'sanitized', 'v1', 0, 1);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('90c10972-2cf2-490f-adaf-73e46775baae', 'b7ffeb9f-db1a-57aa-8ca8-14ad48a6b86d', 'යෂ්ටි හැඩැති, ග්‍රෑම් ධන, අන්තඃ බීජාණු සාදන, ලැක්ටෝස් ද්‍රව රෝපණ මාධ්‍යය $35^{\circ}C$ දී පැසීමෙන් පැය 24 ක් ඇතුළත වායු වර්ග නිපදවන බැක්ටීරියා වේ.', 'යෂ්ටි හැඩැති, ග්‍රෑම් ධන, අන්තඃ බීජාණු සාදන, ලැක්ටෝස් ද්‍රව රෝපණ මාධ්‍යය $35^{\circ}C$ දී පැසීමෙන් පැය 24 ක් ඇතුළත වායු වර්ග නිපදවන බැක්ටීරියා වේ.', NULL, 'sanitized', 'v1', 1, 0);
