INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('7be7a5b3-14a7-4100-9f99-c20a07618298', 'dfbe75a7-0864-5b48-8d4f-1430bdadda73', '(C) සහ (D) යන ප්‍රතිචාර පමණක් නිවැරදි නම්', '(C) සහ (D) යන ප්‍රතිචාර පමණක් නිවැරදි නම්', NULL, 'sanitized', 'v1', 3, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('f27628e2-e3ab-43ed-bd06-ccee650a55d3', 'dfbe75a7-0864-5b48-8d4f-1430bdadda73', 'වෙනත් කිසියම් ප්‍රතිචාරයක් හෝ ප්‍රතිචාර සංයෝජනයක් හෝ නිවැරදි නම්', 'වෙනත් කිසියම් ප්‍රතිචාරයක් හෝ ප්‍රතිචාර සංයෝජනයක් හෝ නිවැරදි නම්', NULL, 'sanitized', 'v1', 4, 0);
INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('6b057cd1-1aff-5aef-81ac-a6de254567d8', '29f5bbf4-11d0-52b2-9c36-80bd6211f940', 42, '<p>ප්‍රෝටිස්ටාවන්ගේ ලක්ෂණ කිහිපයක් සහ එම ලක්ෂණ දරන ජීවීන් පහත දැක්වේ.<br><br>ලක්ෂණය<br>A - ඡවිකාවක් තිබීම<br>B - සංකෝචක රික්තක තිබීම<br>C - ප්‍රභාස්වයංපෝෂී පෝෂණය<br>D - කශිකා මගින් සංචරණය කිරීම<br><br>ජීවියා<br>P - Euglena<br>Q - Amoeba<br>R - Paramecium<br>S - Gelidium<br><br>සියලුම '' ලක්ෂණය - ජීවියා'' සංකලන නිවැරදි වන වරණය/වරණ තෝරන්න.</p>', '<p>ප්‍රෝටිස්ටාවන්ගේ ලක්ෂණ කිහිපයක් සහ එම ලක්ෂණ දරන ජීවීන් පහත දැක්වේ.<br><br>ලක්ෂණය<br>A - ඡවිකාවක් තිබීම<br>B - සංකෝචක රික්තක තිබීම<br>C - ප්‍රභාස්වයංපෝෂී පෝෂණය<br>D - කශිකා මගින් සංචරණය කිරීම<br><br>ජීවියා<br>P - Euglena<br>Q - Amoeba<br>R - Paramecium<br>S - Gelidium<br><br>සියලුම '' ලක්ෂණය - ජීවියා'' සංකලන නිවැරදි වන වරණය/වරණ තෝරන්න.</p>', NULL, 'Paramecium හි දෘඪ එහෙත් නම්‍යශීලී ඡවිකාවක් (pellicle) ඇත (A-R). Amoeba සතුව ආස්‍රැති යාමනය සඳහා සංකෝචක රික්තකයක් පවතී (B-Q). Gelidium යනු රතු ඇල්ගී වර්ගයක් වන අතර එය ප්‍රභාස්වයංපෝෂී වේ (C-S). Euglena කශිකා මගින් සංචරණය කරයි (D-P).', 'Paramecium හි දෘඪ එහෙත් නම්‍යශීලී ඡවිකාවක් (pellicle) ඇත (A-R). Amoeba සතුව ආස්‍රැති යාමනය සඳහා සංකෝචක රික්තකයක් පවතී (B-Q). Gelidium යනු රතු ඇල්ගී වර්ගයක් වන අතර එය ප්‍රභාස්වයංපෝෂී වේ (C-S). Euglena කශිකා මගින් සංචරණය කරයි (D-P).', NULL, 'sanitized', 'v1', 5, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
