INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('fac6b6c1-a711-5cc3-8f63-b2f4b63deb33', '3489872f-fe3a-5615-8855-20ddefeb80ed', 1, '<p>පහත සඳහන් කුමක් භාවිතකරුවකුගේ දත්ත සැකසුම් කාර්යයකට උදාහරණයක් වේද?</p>', '<p>පහත සඳහන් කුමක් භාවිතකරුවකුගේ දත්ත සැකසුම් කාර්යයකට උදාහරණයක් වේද?</p>', NULL, 'දත්ත සැකසුම (Data processing) යනු අමු දත්ත (raw data) අර්ථවත් තොරතුරු (information) බවට පත් කිරීමයි. ශිෂ්‍යයකුගේ සාමාන්‍ය ලකුණු ගණනය කිරීම යනු දත්ත සැකසීමකි.', 'දත්ත සැකසුම (Data processing) යනු අමු දත්ත (raw data) අර්ථවත් තොරතුරු (information) බවට පත් කිරීමයි. ශිෂ්‍යයකුගේ සාමාන්‍ය ලකුණු ගණනය කිරීම යනු දත්ත සැකසීමකි.', NULL, 'sanitized', 'v1', 4, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('249e341f-7c49-4d2f-98ae-2d40e23046b9', 'fac6b6c1-a711-5cc3-8f63-b2f4b63deb33', 'පුද්ගල පරිගණකයකට වදන් සැකසුම් මෘදුකාංගයක් ස්ථාපනය කිරීම', 'පුද්ගල පරිගණකයකට වදන් සැකසුම් මෘදුකාංගයක් ස්ථාපනය කිරීම', NULL, 'sanitized', 'v1', 0, 1);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('95c8d485-6f90-41d7-95aa-749b7231a12e', 'fac6b6c1-a711-5cc3-8f63-b2f4b63deb33', 'පුද්ගල පරිගණකයක දෘඪ ඩිස්කය හැඩසව් (formatting) ගැන්වීම', 'පුද්ගල පරිගණකයක දෘඪ ඩිස්කය හැඩසව් (formatting) ගැන්වීම', NULL, 'sanitized', 'v1', 1, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('f309320c-00d6-467c-9031-640393d5c1a8', 'fac6b6c1-a711-5cc3-8f63-b2f4b63deb33', 'වෙබ් අතරික්සුවක් භාවිත කර මාර්ගගත (online) පුවත්පතක් කියවීම', 'වෙබ් අතරික්සුවක් භාවිත කර මාර්ගගත (online) පුවත්පතක් කියවීම', NULL, 'sanitized', 'v1', 2, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('e62b8188-8503-409e-b2ce-aa639a723abe', 'fac6b6c1-a711-5cc3-8f63-b2f4b63deb33', 'ශිෂ්‍යයකු ලබා ගන්නා ලද සාමාන්‍ය ලකුණු පැතුරුම්පතක් භාවිතයෙන් ගණනය කිරීම', 'ශිෂ්‍යයකු ලබා ගන්නා ලද සාමාන්‍ය ලකුණු පැතුරුම්පතක් භාවිතයෙන් ගණනය කිරීම', NULL, 'sanitized', 'v1', 3, 0);
INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('2687ade7-1907-5271-8bbb-d92561e31b33', '3489872f-fe3a-5615-8855-20ddefeb80ed', 2, '<p>පහත සඳහන් කවර කාණ්ඩයක් ආදාන උපක්‍රම වලින් පමණක් සමන්විත වන්නේ ද?</p>', '<p>පහත සඳහන් කවර කාණ්ඩයක් ආදාන උපක්‍රම වලින් පමණක් සමන්විත වන්නේ ද?</p>', NULL, 'යතුරු පුවරුව (Keyboard), මූසිකය (Mouse), සහ සුපිරික්සකය (Scanner) යන සියල්ලම දත්ත පරිගණකයට ලබා දීමට (Input) යොදාගන්නා උපකරණ වේ.<br><br>අනෙකුත් කාණ්ඩවල CRT මොනිටරය, ප්ලොටරය, මුද්‍රකය වැනි ප්‍රතිදාන (Output) උපකරණ අන්තර්ගත වේ.', 'යතුරු පුවරුව (Keyboard), මූසිකය (Mouse), සහ සුපිරික්සකය (Scanner) යන සියල්ලම දත්ත පරිගණකයට ලබා දීමට (Input) යොදාගන්නා උපකරණ වේ.<br><br>අනෙකුත් කාණ්ඩවල CRT මොනිටරය, ප්ලොටරය, මුද්‍රකය වැනි ප්‍රතිදාන (Output) උපකරණ අන්තර්ගත වේ.', NULL, 'sanitized', 'v1', 4, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('2b1e0d62-fbd1-43ee-87f1-76952e824534', '2687ade7-1907-5271-8bbb-d92561e31b33', 'තීරු කේත කියවනය (Barcode Reader), කැතෝඩ කිරණ නළය සහිත තිරය (CRT Monitor), මෙහෙයුම් යටිය (Joystick)', 'තීරු කේත කියවනය (Barcode Reader), කැතෝඩ කිරණ නළය සහිත තිරය (CRT Monitor), මෙහෙයුම් යටිය (Joystick)', NULL, 'sanitized', 'v1', 0, 1);
