INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('9e1d7575-94dd-456a-8073-a1f7dae1b575', '2687ade7-1907-5271-8bbb-d92561e31b33', 'යතුරු පුවරුව, මූසිකය, සුපිරික්සකය (Scanner)', 'යතුරු පුවරුව, මූසිකය, සුපිරික්සකය (Scanner)', NULL, 'sanitized', 'v1', 2, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('89a56040-6b28-4b45-b0b8-96b0861d98f5', '2687ade7-1907-5271-8bbb-d92561e31b33', 'බහු - මාධ්‍ය ප්‍රක්ෂේපකය (Multimedia Projector), මුද්‍රකය (Printer), සුපිරික්සකය', 'බහු - මාධ්‍ය ප්‍රක්ෂේපකය (Multimedia Projector), මුද්‍රකය (Printer), සුපිරික්සකය', NULL, 'sanitized', 'v1', 3, 0);
INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('85430783-6969-5c28-b5e2-7473b233aa12', '3489872f-fe3a-5615-8855-20ddefeb80ed', 3, '<p>දත්ත ස්ථිර වශයෙන් ආචයනය (store) කිරීම සඳහා පහත සඳහන් දෑ අතුරෙන් කවරක් භාවිත කළ නොහැකි වන්නේ ද?</p>', '<p>දත්ත ස්ථිර වශයෙන් ආචයනය (store) කිරීම සඳහා පහත සඳහන් දෑ අතුරෙන් කවරක් භාවිත කළ නොහැකි වන්නේ ද?</p>', NULL, 'සසම්භාවී ප්‍රවේශ මතකය (RAM) යනු නශ්‍ය (volatile) මතකයක් වන අතර විදුලිය විසන්ධි වූ විට එහි ඇති දත්ත මැකී යයි. එබැවින් දත්ත ස්ථිරව ගබඩා කිරීමට එය භාවිත කළ නොහැක.', 'සසම්භාවී ප්‍රවේශ මතකය (RAM) යනු නශ්‍ය (volatile) මතකයක් වන අතර විදුලිය විසන්ධි වූ විට එහි ඇති දත්ත මැකී යයි. එබැවින් දත්ත ස්ථිරව ගබඩා කිරීමට එය භාවිත කළ නොහැක.', NULL, 'sanitized', 'v1', 4, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
