INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('e9f3445b-4fb1-4bbd-a1e6-704eebc57efc', '71a2122a-7386-5f1a-8867-3b65fe889ad1', 'ප්‍රධාන මතකය, දෘඪ ඩිස්කය, නිහිත මතකය', 'ප්‍රධාන මතකය, දෘඪ ඩිස්කය, නිහිත මතකය', NULL, 'sanitized', 'v1', 3, 0);
INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('aa39c6d1-e310-5a7a-9af2-c5137b6294d6', '3489872f-fe3a-5615-8855-20ddefeb80ed', 5, '<p>.......... ආකාරයේ ජාල ස්ථලකයකදී, එහි වූ සෑම ජාල සංරචකයක්ම නාභියක් (hub) හෝ ස්විචයක් වැනි මධ්‍ය මංසලකට (node) භෞතිකව සම්බන්ධව පවතී.</p>', '<p>.......... ආකාරයේ ජාල ස්ථලකයකදී, එහි වූ සෑම ජාල සංරචකයක්ම නාභියක් (hub) හෝ ස්විචයක් වැනි මධ්‍ය මංසලකට (node) භෞතිකව සම්බන්ධව පවතී.</p>', NULL, 'තාරකා ස්ථලකයකදී (Star topology) සියලුම පරිගණක සහ උපාංග මධ්‍යස්ථාන මංසලකට (Switch හෝ Hub) කෙලින්ම සම්බන්ධ කර ඇත.', 'තාරකා ස්ථලකයකදී (Star topology) සියලුම පරිගණක සහ උපාංග මධ්‍යස්ථාන මංසලකට (Switch හෝ Hub) කෙලින්ම සම්බන්ධ කර ඇත.', NULL, 'sanitized', 'v1', 4, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
