INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('e09e9328-4f57-4599-ae7c-98b3db20a918', '0e6d11cb-0db4-5c66-8af6-39278181f4b7', 'A - නියමාවලිය, B - ඉහළ මට්ටමේ වසම, C - වසම් නාමය', 'A - නියමාවලිය, B - ඉහළ මට්ටමේ වසම, C - වසම් නාමය', NULL, 'sanitized', 'v1', 3, 0);
INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('7ec810ca-f4e0-5ee5-84f9-12984beb67ce', '3489872f-fe3a-5615-8855-20ddefeb80ed', 27, '<p>පහත සඳහන් කුමන සංයෝජනයක් මගින් අන්තර්ජාල සේවාවක් සහ එයට අදාළ වූ නියමාවලිය (protocol) නිවැරදිව පෙන්වනු ලබන්නේ ද?</p>', '<p>පහත සඳහන් කුමන සංයෝජනයක් මගින් අන්තර්ජාල සේවාවක් සහ එයට අදාළ වූ නියමාවලිය (protocol) නිවැරදිව පෙන්වනු ලබන්නේ ද?</p>', NULL, 'විද්‍යුත් තැපෑල (Email) යැවීම සඳහා භාවිත කරන ප්‍රධාන නියමාවලිය වන්නේ SMTP (Simple Mail Transfer Protocol) ය.<br>ලෝක විසිරි වියමන (WWW) සඳහා HTTP ද, ගොනු හුවමාරුව (File Transfer) සඳහා FTP ද යොදා ගැනේ.', 'විද්‍යුත් තැපෑල (Email) යැවීම සඳහා භාවිත කරන ප්‍රධාන නියමාවලිය වන්නේ SMTP (Simple Mail Transfer Protocol) ය.<br>ලෝක විසිරි වියමන (WWW) සඳහා HTTP ද, ගොනු හුවමාරුව (File Transfer) සඳහා FTP ද යොදා ගැනේ.', NULL, 'sanitized', 'v1', 4, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
