INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('3e101eb2-0a0c-4119-8ee2-9d1fdfd56f25', '1f4018a6-e996-5c42-995a-535b7e5dcc0d', 'ග්‍රැෆිකයේ (graphic) තෝරාගත් කොටසක් වෙනත් කොටසකට පිටපත් කරයි', 'ග්‍රැෆිකයේ (graphic) තෝරාගත් කොටසක් වෙනත් කොටසකට පිටපත් කරයි', NULL, 'sanitized', 'v1', 1, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('1f9ea933-404f-4f51-af93-2ceb89474a49', '1f4018a6-e996-5c42-995a-535b7e5dcc0d', 'අනුරුවේ සෙවණැලි ලා පැහැ (lightens) හෝ තද පැහැ (darkens) ගන්වයි', 'අනුරුවේ සෙවණැලි ලා පැහැ (lightens) හෝ තද පැහැ (darkens) ගන්වයි', NULL, 'sanitized', 'v1', 2, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('b4436b44-c7e4-4ddc-97af-e2195afeac5a', '1f4018a6-e996-5c42-995a-535b7e5dcc0d', 'අනුරුවක ඇති අනවශ්‍ය වර්ණ සහ ලප ඉවත් කරයි', 'අනුරුවක ඇති අනවශ්‍ය වර්ණ සහ ලප ඉවත් කරයි', NULL, 'sanitized', 'v1', 3, 0);
INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('dca905ec-e4cd-56a2-ae45-c074a307622b', '3489872f-fe3a-5615-8855-20ddefeb80ed', 29, '<p>A සහ B ලෙස ලේබල් කරන ලද හිස්තැන් සහිත පහත සඳහන් වගන්තිය සලකා බලන්න:<br><br>සෑම වර්ණයක්ම බිටු 8 හි නියෝජනයක් සහිතව නිරූපණය කළේ නම්, පරිගණක තිරය මත අනුරුව නිර්මාණය කිරීමට ...A... යන ප්‍රාථමික වර්ණ භාවිත කරනු ලබන්නේ එක් ප්‍රාථමික වර්ණයක වර්ණ ප්‍රභේදයන් ...B... ක් සමගිනි.</p>', '<p>A සහ B ලෙස ලේබල් කරන ලද හිස්තැන් සහිත පහත සඳහන් වගන්තිය සලකා බලන්න:<br><br>සෑම වර්ණයක්ම බිටු 8 හි නියෝජනයක් සහිතව නිරූපණය කළේ නම්, පරිගණක තිරය මත අනුරුව නිර්මාණය කිරීමට ...A... යන ප්‍රාථමික වර්ණ භාවිත කරනු ලබන්නේ එක් ප්‍රාථමික වර්ණයක වර්ණ ප්‍රභේදයන් ...B... ක් සමගිනි.</p>', NULL, 'පරිගණක තිර (Monitors) මත වර්ණ නිර්මාණය කරන්නේ ආලෝකයේ ප්‍රාථමික වර්ණ වන රතු, කොළ සහ නිල් (RGB) එක් කිරීමෙනි. වර්ණ නිරූපණයට බිටු 8 ක් (8-bit color depth) යොදාගන්නේ නම්, එක් වර්ණයකින් ප්‍රභේද (Shades) $2^8 = 256$ ක් ලබා ගත හැක.', 'පරිගණක තිර (Monitors) මත වර්ණ නිර්මාණය කරන්නේ ආලෝකයේ ප්‍රාථමික වර්ණ වන රතු, කොළ සහ නිල් (RGB) එක් කිරීමෙනි. වර්ණ නිරූපණයට බිටු 8 ක් (8-bit color depth) යොදාගන්නේ නම්, එක් වර්ණයකින් ප්‍රභේද (Shades) $2^8 = 256$ ක් ලබා ගත හැක.', NULL, 'sanitized', 'v1', 4, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
