INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('d049f03c-b89a-42a0-ae6c-e1bc8c3718cc', '0e9d2870-b7c9-5e78-bd00-da1c03d2f602', 'ඔත්තු බැලීමේ මෘදුකාංග (spyware)', 'ඔත්තු බැලීමේ මෘදුකාංග (spyware)', NULL, 'sanitized', 'v1', 2, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('3259fa56-9247-4f68-ae0c-758816f82241', '0e9d2870-b7c9-5e78-bd00-da1c03d2f602', 'ට්‍රෝජන් අශ්වයා (trojan horse)', 'ට්‍රෝජන් අශ්වයා (trojan horse)', NULL, 'sanitized', 'v1', 3, 0);
INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('6421e8aa-0b48-5478-9a41-97b385b15908', '3489872f-fe3a-5615-8855-20ddefeb80ed', 31, '<p>තොරතුරු හා සන්නිවේදන තාක්ෂණය භාවිතය නිසා පහත සඳහන් කවරක් ඉස්මතු විය හැකි වන්නේද?<br><br>A - විද්‍යුත් අපද්‍රව්‍ය ගැටලු<br>B - ආරක්ෂණ තර්ජන<br>C - සෞඛ්‍යමය උපද්‍රව</p>', '<p>තොරතුරු හා සන්නිවේදන තාක්ෂණය භාවිතය නිසා පහත සඳහන් කවරක් ඉස්මතු විය හැකි වන්නේද?<br><br>A - විද්‍යුත් අපද්‍රව්‍ය ගැටලු<br>B - ආරක්ෂණ තර්ජන<br>C - සෞඛ්‍යමය උපද්‍රව</p>', NULL, 'තොරතුරු තාක්ෂණයේ භාවිතය ඉහළ යාමත් සමග ඉලෙක්ට්‍රොනික අපද්‍රව්‍ය (E-waste) ඉහළ යාම, සයිබර් ආරක්ෂණ තර්ජන (Security threats) සහ පරිගණක දෘෂ්ටි සහලක්ෂණය වැනි සෞඛ්‍ය ගැටලු (Health hazards) යන සියල්ලම ඇතිවිය හැක.', 'තොරතුරු තාක්ෂණයේ භාවිතය ඉහළ යාමත් සමග ඉලෙක්ට්‍රොනික අපද්‍රව්‍ය (E-waste) ඉහළ යාම, සයිබර් ආරක්ෂණ තර්ජන (Security threats) සහ පරිගණක දෘෂ්ටි සහලක්ෂණය වැනි සෞඛ්‍ය ගැටලු (Health hazards) යන සියල්ලම ඇතිවිය හැක.', NULL, 'sanitized', 'v1', 4, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
