INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('e833ec75-8e19-5341-9e9c-cae03bac3751', '3606931e-d7be-5c30-a36e-e29533680455', 1, '<p>කැතෝඩ කිරණ නළයක නිරීක්ෂණය කරන ලද කැතෝඩ කිරණ ආශ්‍රිත අංශු සම්බන්ධව නිවැරදි වගන්තිය තෝරන්න.</p>', '<p>කැතෝඩ කිරණ නළයක නිරීක්ෂණය කරන ලද කැතෝඩ කිරණ ආශ්‍රිත අංශු සම්බන්ධව නිවැරදි වගන්තිය තෝරන්න.</p>', NULL, 'කැතෝඩ කිරණ යනු ඉලෙක්ට්‍රෝන ධාරාවකි. ඒවා සෘණ ආරෝපිත අංශු වන බැවින් ඒවායේ ගමන් දිශාව විද්‍යුත් සහ චුම්බක ක්ෂේත්‍ර මගින් උත්ක්‍රමණය (deflect) වේ. එසේම ඒවා ගමන් කරන්නේ කැතෝඩයේ සිට ඇනෝඩය දක්වා ය.', 'කැතෝඩ කිරණ යනු ඉලෙක්ට්‍රෝන ධාරාවකි. ඒවා සෘණ ආරෝපිත අංශු වන බැවින් ඒවායේ ගමන් දිශාව විද්‍යුත් සහ චුම්බක ක්ෂේත්‍ර මගින් උත්ක්‍රමණය (deflect) වේ. එසේම ඒවා ගමන් කරන්නේ කැතෝඩයේ සිට ඇනෝඩය දක්වා ය.', NULL, 'sanitized', 'v1', 5, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('7fa35dd1-118c-428a-bebd-7749707a1b5e', 'e833ec75-8e19-5341-9e9c-cae03bac3751', 'අංශුවලට ආරෝපණයක් නොමැත.', 'අංශුවලට ආරෝපණයක් නොමැත.', NULL, 'sanitized', 'v1', 0, 1);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('4063dbaa-df1f-4d7e-8039-6094f72bb12c', 'e833ec75-8e19-5341-9e9c-cae03bac3751', 'ඒවා ඇනෝඩයේ සිට කැතෝඩය දක්වා සරල රේඛා ඔස්සේ ගමන් කරයි.', 'ඒවා ඇනෝඩයේ සිට කැතෝඩය දක්වා සරල රේඛා ඔස්සේ ගමන් කරයි.', NULL, 'sanitized', 'v1', 1, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('015f3452-9e93-4562-b376-aa68b8da7aa8', 'e833ec75-8e19-5341-9e9c-cae03bac3751', 'ඒවායෙහි ආරෝපණය සහ ස්කන්ධය අතර අනුපාතය $\frac{e}{m}$, කැතෝඩ කිරණ නළය තුළ ඇති වායුවෙහි ස්වභාවය හා පීඩනය මත රඳා පවතී.', 'ඒවායෙහි ආරෝපණය සහ ස්කන්ධය අතර අනුපාතය $\frac{e}{m}$, කැතෝඩ කිරණ නළය තුළ ඇති වායුවෙහි ස්වභාවය හා පීඩනය මත රඳා පවතී.', NULL, 'sanitized', 'v1', 2, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('041e72b5-fe09-48be-8769-8aca7b99c768', 'e833ec75-8e19-5341-9e9c-cae03bac3751', 'ඒවායෙහි ගමන් දිශාවට චුම්බක සහ විද්‍යුත් ක්ෂේත්‍ර බලපායි.', 'ඒවායෙහි ගමන් දිශාවට චුම්බක සහ විද්‍යුත් ක්ෂේත්‍ර බලපායි.', NULL, 'sanitized', 'v1', 3, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('2cb6fa5f-cfe1-482b-bfa9-3ad310d74b02', 'e833ec75-8e19-5341-9e9c-cae03bac3751', 'ඒවාට කැතෝඩ කිරණ නළය තුළ ඇති වායුව අයනීකරණය කිරීමේ හැකියාවක් නොමැත.', 'ඒවාට කැතෝඩ කිරණ නළය තුළ ඇති වායුව අයනීකරණය කිරීමේ හැකියාවක් නොමැත.', NULL, 'sanitized', 'v1', 4, 0);
INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('71feb157-7ec6-5d2c-a287-543167423e76', '3606931e-d7be-5c30-a36e-e29533680455', 2, '<p>පරමාණුවක ප්‍රධාන ක්වොන්ටම් අංකය $(n)$, $n=3$ වන ශක්ති මට්ටම පිළිබඳ මින් කුමන වගන්තිය වැරදි වේද?</p>', '<p>පරමාණුවක ප්‍රධාන ක්වොන්ටම් අංකය $(n)$, $n=3$ වන ශක්ති මට්ටම පිළිබඳ මින් කුමන වගන්තිය වැරදි වේද?</p>', NULL, '$n=3$ ශක්ති මට්ටමේ $l=0, 1, 2$ ($3s, 3p, 3d$) ලෙස උපකවච 3ක් පවතී. ඒවායේ $m_l=0$ වන කාක්ෂික ඇත්තේ එක් උපකවචයකට එක බැගින් සමස්තයක් ලෙස 3කි. එක් කාක්ෂිකයක උපරිම වශයෙන් ඉලෙක්ට්‍රෝන 2ක් පැවතිය හැකි බැවින්, $m_l=0$ සහිත උපරිම ඉලෙක්ට්‍රෝන ගණන $3 \times 2 = 6$ කි. එබැවින් පිළිතුරු 5 වැරදි ප්‍රකාශයකි.', '$n=3$ ශක්ති මට්ටමේ $l=0, 1, 2$ ($3s, 3p, 3d$) ලෙස උපකවච 3ක් පවතී. ඒවායේ $m_l=0$ වන කාක්ෂික ඇත්තේ එක් උපකවචයකට එක බැගින් සමස්තයක් ලෙස 3කි. එක් කාක්ෂිකයක උපරිම වශයෙන් ඉලෙක්ට්‍රෝන 2ක් පැවතිය හැකි බැවින්, $m_l=0$ සහිත උපරිම ඉලෙක්ට්‍රෝන ගණන $3 \times 2 = 6$ කි. එබැවින් පිළිතුරු 5 වැරදි ප්‍රකාශයකි.', NULL, 'sanitized', 'v1', 5, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
