INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('e29fcb00-fd9b-497b-94fd-cbecc6ca645c', '71feb157-7ec6-5d2c-a287-543167423e76', 'එහි උපරිම වශයෙන් ඉලෙක්ට්‍රෝන 18 ක් තිබිය හැකි ය.', 'එහි උපරිම වශයෙන් ඉලෙක්ට්‍රෝන 18 ක් තිබිය හැකි ය.', NULL, 'sanitized', 'v1', 2, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('e5323704-6b27-42a4-a987-32c0fc8d3558', '71feb157-7ec6-5d2c-a287-543167423e76', 'එහි කෝණික ගම්‍යතා (උද්දිගංශ) ක්වොන්ටම් අංකය $(l)$, $l=2$ සහිත ඉලෙක්ට්‍රෝන 10 ක් උපරිම වශයෙන් තිබිය හැකිය.', 'එහි කෝණික ගම්‍යතා (උද්දිගංශ) ක්වොන්ටම් අංකය $(l)$, $l=2$ සහිත ඉලෙක්ට්‍රෝන 10 ක් උපරිම වශයෙන් තිබිය හැකිය.', NULL, 'sanitized', 'v1', 3, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('622515f5-45a8-456b-8dac-4f7a934e139a', '71feb157-7ec6-5d2c-a287-543167423e76', 'එහි චුම්බක ක්වොන්ටම් අංකය $(m_l)$, $m_l=0$ සහිත ඉලෙක්ට්‍රෝන 8ක් උපරිම වශයෙන් තිබිය හැකිය.', 'එහි චුම්බක ක්වොන්ටම් අංකය $(m_l)$, $m_l=0$ සහිත ඉලෙක්ට්‍රෝන 8ක් උපරිම වශයෙන් තිබිය හැකිය.', NULL, 'sanitized', 'v1', 4, 0);
INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('20306f01-aa5b-5d32-a157-4e7b7eb35654', '3606931e-d7be-5c30-a36e-e29533680455', 3, '<p>$H$, $He$, $Li$, $Be$, $B$ සහ $Na$ පරමාණුවල පළමු අයනීකරණ ශක්තිය අඩුවන පිළිවෙළ වනුයේ,</p>', '<p>$H$, $He$, $Li$, $Be$, $B$ සහ $Na$ පරමාණුවල පළමු අයනීකරණ ශක්තිය අඩුවන පිළිවෙළ වනුයේ,</p>', NULL, 'පළමු අයනීකරණ ශක්තිය ආවර්තයක් ඔස්සේ දකුණට යත්ම සාමාන්‍යයෙන් වැඩි වන අතර කාණ්ඩයක් ඔස්සේ පහළට යත්ම අඩු වේ. $He$ පළමු ආවර්තයේ උච්ච වායුවක් බැවින් අයනීකරණ ශක්තිය උපරිම වේ. $Be$ ($2s^2$) පූර්ණ උපකවචයක් ඇති බැවින් $B$ ($2s^2 2p^1$) ට වඩා ස්ථායී වේ. එබැවින් එහි අයනීකරණ ශක්තිය $B$ ට වඩා වැඩිය. නිවැරදි පිළිවෙළ $He > H > Be > B > Li > Na$ වේ.', 'පළමු අයනීකරණ ශක්තිය ආවර්තයක් ඔස්සේ දකුණට යත්ම සාමාන්‍යයෙන් වැඩි වන අතර කාණ්ඩයක් ඔස්සේ පහළට යත්ම අඩු වේ. $He$ පළමු ආවර්තයේ උච්ච වායුවක් බැවින් අයනීකරණ ශක්තිය උපරිම වේ. $Be$ ($2s^2$) පූර්ණ උපකවචයක් ඇති බැවින් $B$ ($2s^2 2p^1$) ට වඩා ස්ථායී වේ. එබැවින් එහි අයනීකරණ ශක්තිය $B$ ට වඩා වැඩිය. නිවැරදි පිළිවෙළ $He > H > Be > B > Li > Na$ වේ.', NULL, 'sanitized', 'v1', 5, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
