INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('12272a8f-bbfc-52a1-9335-44706414dd1b', '3606931e-d7be-5c30-a36e-e29533680455', 4, '<p>$IF_4^+$, $IF_4^-$ හා $IF_5$ හි හැඩයන් වනුයේ පිළිවෙළින්,</p>', '<p>$IF_4^+$, $IF_4^-$ හා $IF_5$ හි හැඩයන් වනුයේ පිළිවෙළින්,</p>', NULL, '$IF_4^+$ මධ්‍ය අයඩින් පරමාණුව වටා බන්ධන යුගල 4ක් හා එක් හුදකලා යුගලයක් පවතින බැවින් හැඩය සීසෝ (Seesaw) වේ. $IF_4^-$ හි බන්ධන යුගල 4ක් හා හුදකලා යුගල 2ක් ඇති බැවින් හැඩය තලීය සමචතුරස්‍රාකාර (Square planar) වේ. $IF_5$ හි බන්ධන යුගල 5ක් හා එක් හුදකලා යුගලයක් ඇති බැවින් හැඩය සමචතුරස්‍ර පිරමීඩාකාර (Square pyramidal) වේ.', '$IF_4^+$ මධ්‍ය අයඩින් පරමාණුව වටා බන්ධන යුගල 4ක් හා එක් හුදකලා යුගලයක් පවතින බැවින් හැඩය සීසෝ (Seesaw) වේ. $IF_4^-$ හි බන්ධන යුගල 4ක් හා හුදකලා යුගල 2ක් ඇති බැවින් හැඩය තලීය සමචතුරස්‍රාකාර (Square planar) වේ. $IF_5$ හි බන්ධන යුගල 5ක් හා එක් හුදකලා යුගලයක් ඇති බැවින් හැඩය සමචතුරස්‍ර පිරමීඩාකාර (Square pyramidal) වේ.', NULL, 'sanitized', 'v1', 5, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('ea983a3e-e558-423a-bc5b-4f03fe6ebbdd', '12272a8f-bbfc-52a1-9335-44706414dd1b', 'සීසෝ, තලීය සමචතුරස්‍රාකාර හා සමචතුරස්‍ර පිරමීඩාකාර ය.', 'සීසෝ, තලීය සමචතුරස්‍රාකාර හා සමචතුරස්‍ර පිරමීඩාකාර ය.', NULL, 'sanitized', 'v1', 0, 1);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('f47ace00-e02b-4fa6-b115-1eb1182bc999', '12272a8f-bbfc-52a1-9335-44706414dd1b', 'තලීය සමචතුරස්‍රාකාර, සීසෝ හා සමචතුරස්‍ර පිරමීඩාකාර ය.', 'තලීය සමචතුරස්‍රාකාර, සීසෝ හා සමචතුරස්‍ර පිරමීඩාකාර ය.', NULL, 'sanitized', 'v1', 1, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('13d1e503-44c3-4a67-b1a6-f8cf14b5a5ee', '12272a8f-bbfc-52a1-9335-44706414dd1b', 'චතුස්තලීය, සීසෝ හා ත්‍රිආනති ද්විපිරමීඩාකාරය.', 'චතුස්තලීය, සීසෝ හා ත්‍රිආනති ද්විපිරමීඩාකාරය.', NULL, 'sanitized', 'v1', 2, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('dabacfb6-6c57-4195-9a8d-98158d738dc6', '12272a8f-bbfc-52a1-9335-44706414dd1b', 'සීසෝ, චතුස්තලීය හා සමචතුරස්‍ර පිරමීඩාකාරය.', 'සීසෝ, චතුස්තලීය හා සමචතුරස්‍ර පිරමීඩාකාරය.', NULL, 'sanitized', 'v1', 3, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('0925a3bd-74f3-4c91-983c-1702306f4e0a', '12272a8f-bbfc-52a1-9335-44706414dd1b', 'චතුස්තලීය, තලීය සමචතුරස්‍රාකාර හා ත්‍රිආනති ද්විපිරමීඩාකාරය.', 'චතුස්තලීය, තලීය සමචතුරස්‍රාකාර හා ත්‍රිආනති ද්විපිරමීඩාකාරය.', NULL, 'sanitized', 'v1', 4, 0);
INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('64e95bae-7f27-52cc-9a5b-763be89be8d8', '3606931e-d7be-5c30-a36e-e29533680455', 5, '<p>පහත දී ඇති සංයෝගයේ IUPAC නාමය කුමක්ද?<br><br>$H_2N-CH_2-CH_2-CH(OH)-C(=CH_2)-CH_2-CH_3$</p>', '<p>පහත දී ඇති සංයෝගයේ IUPAC නාමය කුමක්ද?<br><br>$H_2N-CH_2-CH_2-CH(OH)-C(=CH_2)-CH_2-CH_3$</p>', NULL, 'මෙම සංයෝගයේ ප්‍රධාන ක්‍රියාකාරී කාණ්ඩය ඇල්කොහොල ($-OH$) කාණ්ඩයයි. කාබන් දාමය තේරීමේදී ප්‍රධාන ක්‍රියාකාරී කාණ්ඩය සහ ද්විත්ව බන්ධනය අඩංගු දිගම දාමය තෝරාගත යුතුය. දකුණේ සිට වමට අංකනය කළ විට $-OH$ කාණ්ඩයට අවම අංකය (3) ලැබේ. එබැවින් 5 වන ස්ථානයේ ඇමයිනෝ කාණ්ඩයක්ද, 2 වන ස්ථානයේ ඉතයිල් කාණ්ඩයක්ද පවතී. නිවැරදි නාමය 5-amino-2-ethylpent-1-en-3-ol වේ.', 'මෙම සංයෝගයේ ප්‍රධාන ක්‍රියාකාරී කාණ්ඩය ඇල්කොහොල ($-OH$) කාණ්ඩයයි. කාබන් දාමය තේරීමේදී ප්‍රධාන ක්‍රියාකාරී කාණ්ඩය සහ ද්විත්ව බන්ධනය අඩංගු දිගම දාමය තෝරාගත යුතුය. දකුණේ සිට වමට අංකනය කළ විට $-OH$ කාණ්ඩයට අවම අංකය (3) ලැබේ. එබැවින් 5 වන ස්ථානයේ ඇමයිනෝ කාණ්ඩයක්ද, 2 වන ස්ථානයේ ඉතයිල් කාණ්ඩයක්ද පවතී. නිවැරදි නාමය 5-amino-2-ethylpent-1-en-3-ol වේ.', NULL, 'sanitized', 'v1', 5, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
