INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('e85aca0a-6565-411a-9848-f2f6eeb026bf', 'bb8f2d97-9ece-5e1f-933b-256e09cbaa04', '$Kr$ වලට වඩා ඉහළ තාපාංකයක් $Xe$ වලට ඇත.', '$Kr$ වලට වඩා ඉහළ තාපාංකයක් $Xe$ වලට ඇත.', NULL, 'sanitized', 'v1', 2, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('3af2e052-9648-421a-96a2-5d8302750459', 'bb8f2d97-9ece-5e1f-933b-256e09cbaa04', '$CH_3CH_2CH_2OH$ ට වඩා ඉහළ තාපාංකයක් $CH_3CH_2OH$ වලට ඇත.', '$CH_3CH_2CH_2OH$ ට වඩා ඉහළ තාපාංකයක් $CH_3CH_2OH$ වලට ඇත.', NULL, 'sanitized', 'v1', 3, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('f7426cf2-202d-4889-a2cc-266566c98e67', 'bb8f2d97-9ece-5e1f-933b-256e09cbaa04', '$CH_3CH_2CH_2CH_3$ ට වඩා ඉහළ තාපාංකයක් $CH_3CH(CH_3)_2$ වලට ඇත.', '$CH_3CH_2CH_2CH_3$ ට වඩා ඉහළ තාපාංකයක් $CH_3CH(CH_3)_2$ වලට ඇත.', NULL, 'sanitized', 'v1', 4, 0);
INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('9348dd24-680c-500d-bd4f-4742acf32369', '3606931e-d7be-5c30-a36e-e29533680455', 7, '<p>$M(OH)_2$ යනු ජලයෙහි සුළු වශයෙන් ද්‍රාව්‍ය ඝනයකි. $pH=8.0$ හා දෙන ලද උෂ්ණත්වයකදී $M(OH)_2$ හි සංතෘප්ත ජලීය ද්‍රාවණයක $M^{2+}(aq)$ සාන්ද්‍රණය $1.0 \times 10^{-6} \text{ mol dm}^{-3}$ වේ.<br><br>මෙම උෂ්ණත්වයේදී $M^{2+}(aq)$ සාන්ද්‍රණය $1.0 \times 10^{-4} \text{ mol dm}^{-3}$ වූ $M(OH)_2$ හි සංතෘප්ත ජලීය ද්‍රාවණයක $pH$ අගය වනුයේ,</p>', '<p>$M(OH)_2$ යනු ජලයෙහි සුළු වශයෙන් ද්‍රාව්‍ය ඝනයකි. $pH=8.0$ හා දෙන ලද උෂ්ණත්වයකදී $M(OH)_2$ හි සංතෘප්ත ජලීය ද්‍රාවණයක $M^{2+}(aq)$ සාන්ද්‍රණය $1.0 \times 10^{-6} \text{ mol dm}^{-3}$ වේ.<br><br>මෙම උෂ්ණත්වයේදී $M^{2+}(aq)$ සාන්ද්‍රණය $1.0 \times 10^{-4} \text{ mol dm}^{-3}$ වූ $M(OH)_2$ හි සංතෘප්ත ජලීය ද්‍රාවණයක $pH$ අගය වනුයේ,</p>', NULL, 'ආරම්භක ද්‍රාවණයේ $pH = 8.0$ බැවින් $pOH = 6.0$, එනම් $[OH^-] = 1.0 \times 10^{-6} \text{ mol dm}^{-3}$.<br>$K_{sp} = [M^{2+}][OH^-]^2 = (1.0 \times 10^{-6})(1.0 \times 10^{-6})^2 = 1.0 \times 10^{-18} \text{ mol}^3 \text{ dm}^{-9}$.<br>නව ද්‍රාවණයේ $[M^{2+}] = 1.0 \times 10^{-4} \text{ mol dm}^{-3}$ බැවින්, $[OH^-]^2 = \frac{1.0 \times 10^{-18}}{1.0 \times 10^{-4}} = 1.0 \times 10^{-14}$.<br>එබැවින් $[OH^-] = 1.0 \times 10^{-7} \text{ mol dm}^{-3}$ වේ. $pOH=7.0$ බැවින් $pH=7.0$ වේ.', 'ආරම්භක ද්‍රාවණයේ $pH = 8.0$ බැවින් $pOH = 6.0$, එනම් $[OH^-] = 1.0 \times 10^{-6} \text{ mol dm}^{-3}$.<br>$K_{sp} = [M^{2+}][OH^-]^2 = (1.0 \times 10^{-6})(1.0 \times 10^{-6})^2 = 1.0 \times 10^{-18} \text{ mol}^3 \text{ dm}^{-9}$.<br>නව ද්‍රාවණයේ $[M^{2+}] = 1.0 \times 10^{-4} \text{ mol dm}^{-3}$ බැවින්, $[OH^-]^2 = \frac{1.0 \times 10^{-18}}{1.0 \times 10^{-4}} = 1.0 \times 10^{-14}$.<br>එබැවින් $[OH^-] = 1.0 \times 10^{-7} \text{ mol dm}^{-3}$ වේ. $pOH=7.0$ බැවින් $pH=7.0$ වේ.', NULL, 'sanitized', 'v1', 5, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
