INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('f76f359a-6c07-4525-aaad-34a3af98379f', '9348dd24-680c-500d-bd4f-4742acf32369', '8.0', '8.0', NULL, 'sanitized', 'v1', 4, 0);
INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('c9baa77c-b615-55e4-bcea-d19c08fad413', '3606931e-d7be-5c30-a36e-e29533680455', 8, '<p>නිවැරදි වගන්තිය තෝරන්න.</p>', '<p>නිවැරදි වගන්තිය තෝරන්න.</p>', NULL, 'කාබන් පරමාණුවේ මුහුම්කරණයේ පවතින $s$-ලක්ෂණය අනුව එහි විද්‍යුත් සෘණතාව තීරණය වේ. $CH_4$ හි කාබන් $sp^3$ මුහුම්කරණය ද (25% $s$-ලක්ෂණය), $COCl_2$ හි $sp^2$ ද (33.3% $s$-ලක්ෂණය), $HCN$ හි $sp$ ද (50% $s$-ලක්ෂණය) පෙන්වයි. $s$-ලක්ෂණය වැඩි වන විට විද්‍යුත් සෘණතාව වැඩි වන බැවින් $CH_4 < COCl_2 < HCN$ පිළිවෙළ නිවැරදිය.', 'කාබන් පරමාණුවේ මුහුම්කරණයේ පවතින $s$-ලක්ෂණය අනුව එහි විද්‍යුත් සෘණතාව තීරණය වේ. $CH_4$ හි කාබන් $sp^3$ මුහුම්කරණය ද (25% $s$-ලක්ෂණය), $COCl_2$ හි $sp^2$ ද (33.3% $s$-ලක්ෂණය), $HCN$ හි $sp$ ද (50% $s$-ලක්ෂණය) පෙන්වයි. $s$-ලක්ෂණය වැඩි වන විට විද්‍යුත් සෘණතාව වැඩි වන බැවින් $CH_4 < COCl_2 < HCN$ පිළිවෙළ නිවැරදිය.', NULL, 'sanitized', 'v1', 5, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('06701cf2-4bc1-47f6-9877-69c3b9e74906', 'c9baa77c-b615-55e4-bcea-d19c08fad413', '$SF_5^+$ හි ඉලෙක්ට්‍රෝන යුගල ජ්‍යාමිතිය හා හැඩය එකිනෙකින් වෙනස් ය.', '$SF_5^+$ හි ඉලෙක්ට්‍රෝන යුගල ජ්‍යාමිතිය හා හැඩය එකිනෙකින් වෙනස් ය.', NULL, 'sanitized', 'v1', 0, 1);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('43ee033a-6ec6-4c32-88ad-f27151c17556', 'c9baa77c-b615-55e4-bcea-d19c08fad413', '$F^-$, $Mg^{2+}$, $Al$, $Cl^-$ සහ $K$ පරමාණු/ අයනවල අරයයන් වැඩිවෙන පිළිවෙළ වන්නේ $F^- < Mg^{2+} < Cl^- < Al < K$ ය.', '$F^-$, $Mg^{2+}$, $Al$, $Cl^-$ සහ $K$ පරමාණු/ අයනවල අරයයන් වැඩිවෙන පිළිවෙළ වන්නේ $F^- < Mg^{2+} < Cl^- < Al < K$ ය.', NULL, 'sanitized', 'v1', 1, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('7571b8b3-8411-4cbb-a045-f500f0f7b921', 'c9baa77c-b615-55e4-bcea-d19c08fad413', 'නයිට්‍රික් අම්ලය $(HNO_3)$ සඳහා ඇඳිය හැකි සම්ප්‍රයුක්ත ව්‍යුහ සංඛ්‍යාව හතරකි.', 'නයිට්‍රික් අම්ලය $(HNO_3)$ සඳහා ඇඳිය හැකි සම්ප්‍රයුක්ත ව්‍යුහ සංඛ්‍යාව හතරකි.', NULL, 'sanitized', 'v1', 2, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('3a712d5a-513b-4ebe-932b-48555f7618fe', 'c9baa77c-b615-55e4-bcea-d19c08fad413', '$CO$, $CO_2$, $CO_3^{2-}$ සහ $CH_3OH$ අණු / අයන අතුරෙන් දිගින් වැඩිම $C - O$ බන්ධනය ඇත්තේ $CO_3^{2-}$ වලය.', '$CO$, $CO_2$, $CO_3^{2-}$ සහ $CH_3OH$ අණු / අයන අතුරෙන් දිගින් වැඩිම $C - O$ බන්ධනය ඇත්තේ $CO_3^{2-}$ වලය.', NULL, 'sanitized', 'v1', 3, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('b3907ecc-6a09-4719-95d9-211993f185bd', 'c9baa77c-b615-55e4-bcea-d19c08fad413', '$CH_4$, $COCl_2$ සහ $HCN$ අණු අතුරෙන් කාබන් පරමාණුවෙහි විද්‍යුත් සෘණතාව $CH_4 < COCl_2 < HCN$ යන පිළිවෙළට වැඩි වේ.', '$CH_4$, $COCl_2$ සහ $HCN$ අණු අතුරෙන් කාබන් පරමාණුවෙහි විද්‍යුත් සෘණතාව $CH_4 < COCl_2 < HCN$ යන පිළිවෙළට වැඩි වේ.', NULL, 'sanitized', 'v1', 4, 0);
INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('1c29c75d-c53b-523f-ab13-5f1a4f54ecf8', '3606931e-d7be-5c30-a36e-e29533680455', 9, '<p>$A$ සහ $B$ යනු $C$, $H$ සහ $O$ අඩංගු කාබනික සංයෝග දෙකකි.<br>$A$ සහ $B$ වෙන වෙනම $Br_2/H_2O$ සමග පිරියම් කළ විට, $A$ පමණක් සුදු අවක්ෂේපයක් ලබාදුනි.<br>$B$, සාන්ද්‍ර $H_2SO_4$ සමග රත් කළ විට ලබාදුන් ඵලය $Br_2/H_2O$ විවර්ණ කළේය. $A$ සහ $B$ කාබනික සංයෝග වනුයේ පිළිවෙළින්,</p>', '<p>$A$ සහ $B$ යනු $C$, $H$ සහ $O$ අඩංගු කාබනික සංයෝග දෙකකි.<br>$A$ සහ $B$ වෙන වෙනම $Br_2/H_2O$ සමග පිරියම් කළ විට, $A$ පමණක් සුදු අවක්ෂේපයක් ලබාදුනි.<br>$B$, සාන්ද්‍ර $H_2SO_4$ සමග රත් කළ විට ලබාදුන් ඵලය $Br_2/H_2O$ විවර්ණ කළේය. $A$ සහ $B$ කාබනික සංයෝග වනුයේ පිළිවෙළින්,</p>', NULL, 'ෆීනෝල් ($C_6H_5OH$) $Br_2/H_2O$ සමඟ 2,4,6-tribromophenol නැමති සුදු අවක්ෂේපයක් ලබා දෙයි. එබැවින් $A$ යනු $C_6H_5OH$ වේ.<br>$B$ ලෙස ඇති අයිසොප්‍රොපනෝල් ($CH_3CH(OH)CH_3$) සාන්ද්‍ර $H_2SO_4$ සමඟ රත් කල විට විජලනය වී ප්‍රොපීන් ($CH_3CH=CH_2$) සාදයි. මෙය ඇල්කීනයක් බැවින් $Br_2/H_2O$ විවර්ණ කරයි.', 'ෆීනෝල් ($C_6H_5OH$) $Br_2/H_2O$ සමඟ 2,4,6-tribromophenol නැමති සුදු අවක්ෂේපයක් ලබා දෙයි. එබැවින් $A$ යනු $C_6H_5OH$ වේ.<br>$B$ ලෙස ඇති අයිසොප්‍රොපනෝල් ($CH_3CH(OH)CH_3$) සාන්ද්‍ර $H_2SO_4$ සමඟ රත් කල විට විජලනය වී ප්‍රොපීන් ($CH_3CH=CH_2$) සාදයි. මෙය ඇල්කීනයක් බැවින් $Br_2/H_2O$ විවර්ණ කරයි.', NULL, 'sanitized', 'v1', 5, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
