INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('a2f64a7c-e1da-598d-8fc0-be1367410c49', '3606931e-d7be-5c30-a36e-e29533680455', 11, '<p>පහත දැක්වෙන සංයෝගය (3-බ්‍රෝමොනයිට්‍රොබෙන්සීන්) සාදා ගැනීමට සුදුසු ක්‍රමයක් වනුයේ,</p>', '<p>පහත දැක්වෙන සංයෝගය (3-බ්‍රෝමොනයිට්‍රොබෙන්සීන්) සාදා ගැනීමට සුදුසු ක්‍රමයක් වනුයේ,</p>', NULL, 'ඉලක්ක සංයෝගයේ $-Br$ සහ $-NO_2$ කාණ්ඩ මෙටා (meta) පිහිටුම් වල පවතී. බෙන්සීන් වළල්ලේ ඇති $-NO_2$ කාණ්ඩය ප්‍රබල මෙටා-දිශානතිකරණ (meta-directing) කාණ්ඩයකි. එබැවින් නයිට්‍රොබෙන්සීන් ලුවිස් අම්ල උත්ප්‍රේරකයක් ($FeBr_3$) හමුවේ බ්‍රෝමිනීකරණය ($Br_2$) කළ විට සෘජුවම 3-බ්‍රෝමොනයිට්‍රොබෙන්සීන් ප්‍රධාන ඵලය ලෙස ලබා ගත හැක.', 'ඉලක්ක සංයෝගයේ $-Br$ සහ $-NO_2$ කාණ්ඩ මෙටා (meta) පිහිටුම් වල පවතී. බෙන්සීන් වළල්ලේ ඇති $-NO_2$ කාණ්ඩය ප්‍රබල මෙටා-දිශානතිකරණ (meta-directing) කාණ්ඩයකි. එබැවින් නයිට්‍රොබෙන්සීන් ලුවිස් අම්ල උත්ප්‍රේරකයක් ($FeBr_3$) හමුවේ බ්‍රෝමිනීකරණය ($Br_2$) කළ විට සෘජුවම 3-බ්‍රෝමොනයිට්‍රොබෙන්සීන් ප්‍රධාන ඵලය ලෙස ලබා ගත හැක.', NULL, 'sanitized', 'v1', 5, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('e10dea75-acb5-47a0-b09e-522ad987b16e', 'a2f64a7c-e1da-598d-8fc0-be1367410c49', 'නයිට්‍රොබෙන්සීන් $\xrightarrow{NaNO_2 / \text{තනුක } HCl / 0 - 5 ^\circ C} \dots$', 'නයිට්‍රොබෙන්සීන් $\xrightarrow{NaNO_2 / \text{තනුක } HCl / 0 - 5 ^\circ C} \dots$', NULL, 'sanitized', 'v1', 0, 1);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('643595c8-2800-4bf6-a10e-28a4cf184ff1', 'a2f64a7c-e1da-598d-8fc0-be1367410c49', 'ඇනිලීන් $\xrightarrow{Br_2/FeBr_3} \xrightarrow{NaNO_2 / \text{තනුක } HCl / 0 - 5 ^\circ C} \xrightarrow{H_3PO_2}$', 'ඇනිලීන් $\xrightarrow{Br_2/FeBr_3} \xrightarrow{NaNO_2 / \text{තනුක } HCl / 0 - 5 ^\circ C} \xrightarrow{H_3PO_2}$', NULL, 'sanitized', 'v1', 1, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('8060bc61-11cb-491c-b6e1-12172d2fe950', 'a2f64a7c-e1da-598d-8fc0-be1367410c49', 'නයිට්‍රොබෙන්සීන් $\xrightarrow{Br_2/FeBr_3}$', 'නයිට්‍රොබෙන්සීන් $\xrightarrow{Br_2/FeBr_3}$', NULL, 'sanitized', 'v1', 2, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('ba78ac5a-4e2a-43c3-842c-4b43a8a5af1c', 'a2f64a7c-e1da-598d-8fc0-be1367410c49', 'නයිට්‍රොබෙන්සීන් $\xrightarrow{Sn/HCl} \xrightarrow{Br_2} \xrightarrow{NaNO_2/HCl} \xrightarrow{CuBr}$', 'නයිට්‍රොබෙන්සීන් $\xrightarrow{Sn/HCl} \xrightarrow{Br_2} \xrightarrow{NaNO_2/HCl} \xrightarrow{CuBr}$', NULL, 'sanitized', 'v1', 3, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('d183242b-f70e-4bc7-9c01-60146f61f9ef', 'a2f64a7c-e1da-598d-8fc0-be1367410c49', 'බ්‍රෝමොබෙන්සීන් $\xrightarrow{\text{සාන්ද්‍ර } HNO_3 / \text{සාන්ද්‍ර } H_2SO_4}$', 'බ්‍රෝමොබෙන්සීන් $\xrightarrow{\text{සාන්ද්‍ර } HNO_3 / \text{සාන්ද්‍ර } H_2SO_4}$', NULL, 'sanitized', 'v1', 4, 0);
INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('d995eaf8-1e44-5fb2-a986-d411fd2985ab', '3606931e-d7be-5c30-a36e-e29533680455', 12, '<p>$0.150 \text{ mol dm}^{-3} HNO_3$ ද්‍රාවණයක $300 \text{ cm}^3$ පිළියෙළ කිරීම සඳහා අවශ්‍ය, ඝනත්වය $1.42 \text{ g cm}^{-3}$ වන $70.0\% (w/w)$ සාන්ද්‍ර $HNO_3$ අම්ලයෙහි නිවැරදි පරිමාව $(\text{cm}^3)$ කුමන ප්‍රකාශනයෙන් දැක්වේ ද?<br><br>(සාපේක්ෂ පරමාණුක ස්කන්ධය: $H=1, N=14, O=16$)</p>', '<p>$0.150 \text{ mol dm}^{-3} HNO_3$ ද්‍රාවණයක $300 \text{ cm}^3$ පිළියෙළ කිරීම සඳහා අවශ්‍ය, ඝනත්වය $1.42 \text{ g cm}^{-3}$ වන $70.0\% (w/w)$ සාන්ද්‍ර $HNO_3$ අම්ලයෙහි නිවැරදි පරිමාව $(\text{cm}^3)$ කුමන ප්‍රකාශනයෙන් දැක්වේ ද?<br><br>(සාපේක්ෂ පරමාණුක ස්කන්ධය: $H=1, N=14, O=16$)</p>', NULL, 'අවශ්‍ය ශුද්ධ $HNO_3$ මවුල ගණන = $\frac{0.150}{1000} \times 300$.<br>ශුද්ධ $HNO_3$ ස්කන්ධය = $\left( \frac{0.150}{1000} \times 300 \right) \times 63 \text{ g}$.<br>වාණිජ අම්ල ද්‍රාවණයේ අවශ්‍ය ස්කන්ධය = $\left( \frac{0.150}{1000} \times 300 \right) \times 63 \times \frac{100}{70.0} \text{ g}$.<br>එහි පරිමාව ($V = m/d$) = $\frac{1}{1.42} \times \left( \frac{0.150}{1000} \times 300 \right) \times 63 \times \frac{100}{70.0}$.<br>මෙය යළි සැකසූ විට $\frac{100}{1.42} \times \frac{63}{70.0} \times \frac{0.150}{1000} \times 300$ ලැබේ.', 'අවශ්‍ය ශුද්ධ $HNO_3$ මවුල ගණන = $\frac{0.150}{1000} \times 300$.<br>ශුද්ධ $HNO_3$ ස්කන්ධය = $\left( \frac{0.150}{1000} \times 300 \right) \times 63 \text{ g}$.<br>වාණිජ අම්ල ද්‍රාවණයේ අවශ්‍ය ස්කන්ධය = $\left( \frac{0.150}{1000} \times 300 \right) \times 63 \times \frac{100}{70.0} \text{ g}$.<br>එහි පරිමාව ($V = m/d$) = $\frac{1}{1.42} \times \left( \frac{0.150}{1000} \times 300 \right) \times 63 \times \frac{100}{70.0}$.<br>මෙය යළි සැකසූ විට $\frac{100}{1.42} \times \frac{63}{70.0} \times \frac{0.150}{1000} \times 300$ ලැබේ.', NULL, 'sanitized', 'v1', 5, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
